// Üretilen dosya: tool/ozgun/uret.py. Bilişim ve Algoritmalar · Nesne yönelimli programlama kavramları (orta).
const ozComputing9Orta = <(String, String, List<String>, String)>[
  ('Grady Booch\'un nesne tanımına göre her nesneyi niteleyen üç temel özellik hangileridir?', 'Durum, davranış ve kimlik', ['Ad, tür, boyut ve renk', 'Sınıf, paket ve modül', 'Alan, adres ve değer'], 'Booch\'a göre bir nesnenin alanlarının değerleri durumunu, yöntemleri davranışını oluşturur; kimlik ise onu aynı durumdaki başka nesnelerden ayırır.'),
  ('Java\'da String a = new String("ab"); String b = new String("ab"); satırlarından sonra a == b ve a.equals(b) ifadeleri sırasıyla hangi değerleri verir?', 'false ve true', ['true ve true', 'true ve false', 'false ve false'], 'new her seferinde ayrı bir nesne oluşturduğu için == ile yapılan başvuru karşılaştırması false verir; equals ise karakter içeriklerini karşılaştırıp true döndürür.'),
  ('Python\'da a = [1, 2] ve b = [1, 2] olarak iki ayrı liste oluşturuluyor. a == b ve a is b ifadeleri sırasıyla ne verir?', 'True ve False', ['True ve True', 'False ve True', 'False ve False'], '== içerik eşitliğine bakar ve iki liste aynı öğeleri taşıdığı için True verir; is ise aynı nesne olup olmadıklarını sınar ve iki ayrı liste olduğundan False döner.'),
  ('Java\'da Object sınıfından devralınan equals yöntemi bir alt sınıfta geçersiz kılınmazsa iki nesneyi neye göre karşılaştırır?', 'Aynı nesneyi gösterip göstermediklerine', ['Bütün alanlarının değerlerine', 'Sınıf adlarının aynı olmasına', 'toString yöntemlerinin çıktılarının eşitliğine'], 'Object.equals varsayılan olarak == ile aynı işi yapar, yani yalnız iki başvurunun aynı nesneyi göstermesi durumunda true döndürür.'),
  ('Python\'da içi boş class Nokta: pass tanımlanıp p = Nokta() ve q = Nokta() oluşturuluyor. p == q ifadesi neden False verir?', '__eq__ tanımlanmadığından kimlik karşılaştırılır', ['Boş sınıfların nesneleri karşılaştırılamaz', '== işleci yalnız sayılarda çalışır', 'Nesnelerin alanları farklı rastgele değerler alır'], 'Sınıf __eq__ yöntemini tanımlamazsa object\'ten gelen varsayılan davranış iki nesnenin aynı nesne olup olmadığına bakar; p ve q ayrı nesneler olduğu için sonuç False olur.'),
  ('Python\'da def selamla(self): biçiminde tanımlanan bir örnek yöntemi ali.selamla() diye çağrılıyor. self parametresi için hangisi doğrudur?', 'Çağrıda ali nesnesi otomatik olarak ona bağlanır', ['Çağıran kişinin ayrıca bir değer vermesi gerekir', 'Sınıfın kendisine bağlanır, nesneye bağlanmaz', 'Python\'da ayrılmış bir sözcük olduğundan değiştirilemez'], 'ali.selamla() çağrısı Sinif.selamla(ali) ile eşdeğerdir; nesne ilk parametreye otomatik geçer. self ayrılmış sözcük değil, yalnızca güçlü bir adlandırma geleneğidir.'),
  ('CPython\'da bir nesnenin yaşamı boyunca değişmeyen ve bellek adresine dayanan kimlik tamsayısını veren yerleşik işlev hangisidir?', 'id()', ['hash()', 'type()', 'vars()'], 'id() nesnenin kimliğini döndürür; iki ifade için a is b ancak id(a) == id(b) olduğunda doğrudur.'),
  ('JavaScript\'te {a: 1} === {a: 1} ifadesinin değeri nedir ve neden?', 'false; iki ayrı nesne oluşturulur', ['true; alanlar ve değerler aynıdır', 'true; === yalnız türleri karşılaştırır', 'false; nesneler karşılaştırılamaz'], 'JavaScript\'te nesneler başvuruyla karşılaştırılır. İki nesne değişmezi bellekte iki ayrı nesne oluşturduğundan === false verir.'),
  ('Java\'da Kisi sınıfına yalnız Kisi(String ad) yapıcısı yazılmıştır. Başka bir yerde new Kisi() yazılırsa ne olur?', 'Derleme hatası oluşur', ['ad alanı null olan bir nesne oluşur', 'ad alanı boş metin olan bir nesne oluşur', 'Çalışma anında istisna fırlatılır'], 'Programcı herhangi bir yapıcı yazdığında derleyici artık varsayılan parametresiz yapıcıyı eklemez; bu yüzden parametresiz çağrı derlenemez.'),
  ('Java\'da bir yapıcının içinden aynı sınıfın başka bir yapıcısı this(...) ile çağrılacaksa hangi kurala uyulmalıdır?', 'Bu çağrı yapıcının ilk deyimi olmalıdır', ['Bu çağrı yapıcının son deyimi olmalıdır', 'Çağrılan yapıcı static olmalıdır', 'Çağrı yalnız bir döngü içinde yapılabilir'], 'this(...) ve super(...) çağrıları yapıcı gövdesinin ilk deyimi olmak zorundadır; böylece nesne önce tutarlı biçimde başlatılır.'),
  ('Java\'da C sınıfı B\'den, B sınıfı da A\'dan türetilmiştir ve her sınıfın yapıcısı yalnız kendi harfini yazdırır. new C() çalıştırıldığında çıktı nedir?', 'ABC', ['CBA', 'C', 'CAB'], 'Her yapıcı önce örtük super() çağrısıyla üst sınıfın yapıcısını çalıştırır. Bu yüzden başlatma en üstteki atadan aşağı doğru ilerler: A, B, C.'),
  ('C++\'ta Taban sınıfından Turemis sınıfı türetilmiştir. Yığında oluşturulan bir Turemis nesnesinin kapsamı bittiğinde yıkıcılar hangi sırayla çalışır?', 'Önce ~Turemis, sonra ~Taban', ['Önce ~Taban, ardından ~Turemis', 'Yalnız ~Turemis çalışır', 'Yalnız ~Taban çalışır'], 'Yıkım, yapımın tersi sırasıyla yapılır: nesne tabandan türemişe doğru kurulur, türemişten tabana doğru yıkılır.'),
  ('C++\'ta yaygın olan RAII (Resource Acquisition Is Initialization) deyimi neyi önerir?', 'Kaynağın yapıcıda edinilip yıkıcıda bırakılmasını', ['Kaynakların yalnız genel değişkenlerde tutulmasını', 'Belleğin çöp toplayıcıya bırakılmasını', 'Her kaynağın elle iki kez kapatılmasını'], 'RAII\'de bir dosya, kilit ya da bellek gibi kaynak bir nesnenin ömrüne bağlanır; nesne kapsamdan çıkınca yıkıcı kaynağı kendiliğinden bırakır.'),
  ('Python\'da class Kisi: def __init__(self, ad): self.ad = ad tanımlıdır. Kisi() çağrısı yapılırsa ne olur?', 'TypeError fırlatılır', ['ad niteliği None olur', 'ad niteliği boş metin olur', 'Nesne niteliksiz oluşur'], '__init__ zorunlu ad parametresi bekler; argüman verilmediğinde Python eksik konumsal argüman bildiren bir TypeError fırlatır.'),
  ('Python\'da Ogrenci(Kisi) alt sınıfı kendi __init__ yöntemini yazıyor ama super().__init__(ad) çağrısını unutuyor. Kisi\'nin __init__\'te atadığı ad niteliğine bir Ogrenci nesnesinde erişilirse ne olur?', 'AttributeError alınır', ['ad niteliği None olarak döner', 'Kisi\'nin __init__\'i yine kendiliğinden çalışır', 'Nesne oluşturulurken SyntaxError alınır'], 'Python\'da üst sınıfın __init__\'i kendiliğinden çağrılmaz; alt sınıf onu çağırmazsa üst sınıfın atadığı nitelikler hiç oluşmaz.'),
  ('Java\'da try (BufferedReader r = ...) { ... } biçimindeki kaynaklı try bloğunda kullanılan nesnenin türü hangi arayüzü uygulamalıdır?', 'AutoCloseable', ['Serializable', 'Comparable', 'Cloneable'], 'Kaynaklı try, blok bitince kaynağın close() yöntemini otomatik çağırır; bu yüzden kaynak AutoCloseable (ya da onu genişleten Closeable) arayüzünü uygulamalıdır.'),
  ('Python\'da with ifadesiyle kullanılabilen bir bağlam yöneticisi sınıfı hangi iki özel yöntemi tanımlamalıdır?', '__enter__ ve __exit__', ['__open__ ve __close__', '__init__ ve __del__', '__start__ ve __stop__'], 'with bloğuna girerken __enter__, bloktan çıkarken (hata olsa bile) __exit__ çağrılır; böylece kaynak düzenli biçimde bırakılır.'),
  ('Java\'da bir sınıfın int türündeki alanına değer verilmezse alan 0 olur; ancak bir yöntem içindeki int yerel değişken değer verilmeden okunursa ne olur?', 'Derleme hatası oluşur', ['Değeri yine 0 olur', 'Rastgele bir değer okunur', 'Çalışma anında istisna oluşur'], 'Java alanlara varsayılan değer verir ama yerel değişkenlere vermez; derleyici ilk değer atanmadan okunan yerel değişkeni hata olarak bildirir.'),
  ('Java\'da Object\'ten başka bir üst sınıf belirtilmeyen bir sınıfın yapıcısında bile örtük olarak hangi çağrı yapılır?', 'super()', ['this()', 'finalize()', 'main()'], 'Açıkça this(...) ya da super(...) yazılmamışsa derleyici her yapıcının başına örtük super() ekler; doğrudan üst sınıf belirtilmemişse bu Object\'in yapıcısıdır.'),
  ('Java\'da protected olarak bildirilen bir alana hangi kodlar erişebilir?', 'Aynı paketteki sınıflar ve alt sınıflar', ['Yalnız tanımlandığı sınıfın kendisi ve iç sınıfları', 'Yalnız başka paketlerdeki sınıflar', 'Programdaki bütün sınıflar'], 'Java\'da protected erişim, aynı paketteki tüm sınıflara ve başka paketlerde olsa bile alt sınıflara izin verir.'),
  ('Java\'da hiçbir erişim belirleyicisi yazılmadan tanımlanan bir yönteme hangi kodlar erişebilir?', 'Yalnız aynı paketteki sınıflar', ['Programdaki bütün sınıflar', 'Yalnız alt sınıflar', 'Yalnız aynı sınıf'], 'Belirleyici yazılmazsa paket düzeyi (package-private) erişim geçerli olur; başka paketlerdeki sınıflar, alt sınıf olsalar bile, bu üyeye erişemez.'),
  ('C++\'ta bir sınıfın, başka bir sınıfa ya da işleve kendi private üyelerine erişim izni vermek için kullandığı anahtar sözcük hangisidir?', 'friend', ['public', 'extern', 'mutable'], 'friend bildirimi, belirtilen işlev ya da sınıfın kapsülleme sınırını aşarak özel üyelere erişmesine izin verir; bu yüzden ölçülü kullanılmalıdır.'),
  ('Python\'da bir yöntemin üzerine @property süslemesi konmasının etkisi nedir?', 'Yöntem parantezsiz, nitelik gibi okunabilir', ['Yöntem yalnız sınıf adıyla çağrılabilir', 'Yöntemin sonucu kalıcı olarak diske yazılıp saklanır', 'Yöntem alt sınıflarda geçersiz kılınamaz'], '@property ile tanımlanan yöntem nesne.alan biçiminde okunur; böylece arka planda hesaplama ya da denetim yapılırken dış arayüz basit bir nitelik gibi kalır.'),
  ('Python\'da Daire sınıfında yalnız @property ile alan adlı okuma yöntemi tanımlanmış, setter yazılmamıştır. d.alan = 10 ataması yapılırsa ne olur?', 'AttributeError fırlatılır', ['alan değeri 10 olur', 'Atama sessizce yok sayılır', 'Yeni bir alan niteliği oluşur'], 'Setter tanımlanmamış bir property salt okunurdur; Python ona atama yapılmasını AttributeError ile reddeder.'),
  ('Python\'da @yas.setter ile tanımlanan bir yöntemin içinde negatif değer gelince ValueError fırlatılıyor. Bu tasarımın doğrudan bir alan kullanmaya göre yararı nedir?', 'Atamalarda doğrulama yapılırken sözdizimi değişmez', ['Nesne bellekte daha az yer kaplar', 'Alan bütün nesnelerce paylaşılır', 'Yöntemler derleme zamanında çalışır'], 'Kullanıcı yine kisi.yas = 20 yazar; ancak her atama setter\'dan geçtiği için geçersiz değerler nesnenin durumuna giremez.'),
  ('Bir alanı doğrudan public yapmak yerine erişimci (getter) ve değiştirici (setter) yöntemler üzerinden açmanın başlıca yararı hangisidir?', 'İç gösterim, kullanıcı kodu bozulmadan değiştirilebilir', ['Program her durumda daha hızlı çalışır', 'Alan bütün alt sınıflardan ve paketten tümüyle gizlenmiş olur', 'Derleyici alanın türünü kendisi belirler'], 'Yöntemler bir arayüz oluşturur; sınıf içte veriyi başka biçimde saklamaya başlasa da, doğrulama eklese de dışarıdaki kod aynı çağrıları kullanmaya devam eder.'),
  ('Bir nesneden verilerini isteyip kararı dışarıda vermek yerine, nesneye işi yapmasını söylemeyi öneren nesne yönelimli tasarım ilkesi hangisidir?', 'Sorma, söyle (Tell, Don\'t Ask)', ['Kendini tekrar etme (DRY)', 'Basit tut (KISS)', 'Buna ihtiyacın olmayacak (YAGNI)'], 'Tell, Don\'t Ask ilkesine göre davranış, verinin bulunduğu nesnede olmalıdır; örneğin hesabın bakiyesini okuyup dışarıda düşmek yerine hesap.cek(tutar) çağrılır.'),
  ('C#\'ta public int Puan { get; private set; } biçiminde tanımlanan özellik için hangisi doğrudur?', 'Herkes okuyabilir, yalnız sınıfın kendisi değiştirebilir', ['Herkes okuyup değiştirebilir', 'Yalnız alt sınıflar okuyabilir', 'Hiç kimse değiştiremez, yalnız okunur'], 'get erişimcisi public, set erişimcisi private olduğundan değer dışarıdan okunabilir; atama yalnız sınıf içindeki kodda yapılabilir.'),
  ('Java Bean adlandırma geleneğine göre boolean türündeki aktif alanının okuma yöntemi genellikle nasıl adlandırılır?', 'isAktif()', ['getAktifMi()', 'aktifOku()', 'hasAktif()'], 'Bean geleneğinde boolean alanlar için is önekli okuma yöntemi (isAktif), diğer türler için get önekli yöntem (getAd) kullanılır.'),
  ('UML sınıf diyagramında bir üyenin önündeki \'#\' işareti hangi erişim düzeyini belirtir?', 'protected', ['public', 'private', 'static'], 'UML\'de + public, - private, # protected ve ~ paket düzeyi erişimi gösterir.'),
  ('Bir Sicaklik sınıfı değeri içte Kelvin olarak tutarken getCelsius() ve setCelsius() yöntemleriyle dışarıya Celsius cinsinden sunuyor. Bu durum hangi yararı en iyi örnekler?', 'Dış arayüz ile iç gösterimin birbirinden bağımsız olması', ['Alt sınıfların program bozulmadan üst sınıf yerine kullanılabilmesi', 'Aynı adlı yöntemlerin farklı parametre alması', 'Nesnenin tek bir kopyasının bulunması'], 'Kullanıcılar yalnız Celsius ile çalışır; sınıf içteki birimi değiştirse bile arayüz aynı kaldığı için dış kod etkilenmez. Bu, kapsüllemenin temel kazancıdır.'),
  ('Java\'da static bir yöntemin içinden aynı sınıfın static olmayan bir alanına doğrudan (nesne belirtmeden) erişilmeye çalışılırsa ne olur?', 'Derleme hatası oluşur', ['Alanın varsayılan değeri okunur', 'İlk oluşturulan nesnenin alanı okunur', 'Çalışma anında NullPointerException alınır'], 'Statik yöntem belirli bir nesneye bağlı değildir; hangi nesnenin alanının kastedildiği belli olmadığından derleyici bu erişime izin vermez.'),
  ('Java\'da Sayac sınıfında static int toplam = 0; ve int kendi = 0; alanları var; yapıcı ikisini de birer artırıyor. Üç nesne oluşturulduktan sonra üçüncü nesne için toplam ve kendi değerleri nedir?', '3 ve 1', ['3 ve 3', '1 ve 1', '1 ve 3'], 'Statik alan tek kopya olduğundan her yapıcı aynı sayacı artırır ve 3\'e ulaşır. Örnek alanı her nesnede ayrı olduğu için her nesnede yalnız bir kez artırılır.'),
  ('Python\'da @classmethod ile @staticmethod süslemeleri arasındaki fark hangisidir?', 'classmethod ilk parametre olarak sınıfı alır, staticmethod örtük parametre almaz', ['staticmethod ilk parametre olarak nesneyi alır, classmethod almaz', 'İkisi de ilk parametre olarak nesneyi alır', 'classmethod yalnız soyut sınıflarda kullanılabilir'], '@classmethod yöntemine çağrıldığı sınıf cls olarak geçirilir; @staticmethod ise sınıf içinde duran sıradan bir işlev gibidir ve ne self ne cls alır.'),
  ('Python\'da class Ayar: dil = "tr" tanımlı ve iki nesne oluşturulmuş; hiçbirinde dil niteliği atanmamış. Ardından Ayar.dil = "en" yapılırsa nesnelerden okunan dil değeri ne olur?', '"en"', ['"tr"', 'None', 'Nesneye göre değişir'], 'Nesnede aynı adlı nitelik yoksa arama sınıfa uzanır; sınıf niteliği değiştirildiği için her iki nesneden de yeni değer okunur.'),
  ('Python\'da Tarih sınıfına, \'2024-05-19\' gibi bir metinden nesne üreten \'metinden\' adlı alternatif yapıcı eklenecek. Bu yöntem için en uygun süsleme hangisidir?', '@classmethod', ['@property', '@abstractmethod', '@staticmethod ile self'], 'Alternatif yapıcılar cls parametresiyle cls(yil, ay, gun) döndürür; böylece alt sınıftan çağrıldığında da doğru türde nesne üretilir.'),
  ('Alt sınıflardaki ortak özelliklerin bir araya toplanarak yeni bir üst sınıf oluşturulmasına ne ad verilir?', 'Genelleme', ['Özelleştirme', 'Örnekleme', 'Bileşim'], 'Aşağıdan yukarıya, ortak yönleri üst sınıfa taşımak genellemedir; yukarıdan aşağıya yeni ayrıntılar ekleyerek alt sınıf türetmek ise özelleştirmedir.'),
  ('Python\'da Kare(Dikdortgen) sınıfının __init__(self, kenar) yöntemi, üst sınıfın __init__(self, en, boy) yöntemini kullanmak istiyor. En uygun çağrı hangisidir?', 'super().__init__(kenar, kenar)', ['super.__init__(self, kenar)', 'Dikdortgen(kenar, kenar)', 'self.__init__(kenar, kenar)'], 'super() üst sınıfa bağlı bir vekil döndürür ve self\'i kendisi geçirir. Dikdortgen(...) yeni bir nesne oluşturur; self.__init__ ise kendini sonsuz kez çağırır.'),
  ('Java\'da geçersiz kılınan bir yöntemin üzerine @Override ek açıklamasını (annotation) yazmanın yararı nedir?', 'İmza üst sınıfla uyuşmazsa derleyici hata verir', ['Yöntem çalışma anında daha hızlı yürütülür', 'Yöntem alt sınıflarda yeniden yazılamaz hale gelir', 'Üst sınıftaki yöntem otomatik olarak silinir'], '@Override derleyiciye bu yöntemin bir üst türdeki yöntemi geçersiz kılması gerektiğini söyler; yazım ya da parametre hatası yüzünden yanlışlıkla yeni bir yöntem oluşursa derleme başarısız olur.'),
  ('Java\'da bir sınıfta int hesapla(int x) ve double hesapla(int x) yöntemleri birlikte tanımlanırsa ne olur?', 'Derleme hatası; yalnız dönüş türü farklıdır', ['İki yöntem aşırı yüklenmiş olarak çalışır', 'Çağrıdaki değişkenin türüne göre biri seçilir', 'Sonradan yazılan yöntem öncekini geçersiz kılar'], 'Aşırı yüklemede yöntemler parametre listeleriyle ayırt edilir; dönüş türü imzaya dahil değildir, bu yüzden iki yöntem aynı imzayı taşır ve derleme başarısız olur.'),
  ('C++\'ta Taban sınıfındaki ses() işlevi virtual olarak bildirilmemiştir. Taban* p = new Kedi(); p->ses(); çağrısında hangi işlev çalışır?', 'Taban::ses()', ['Kedi::ses()', 'İkisi de sırayla çalışır', 'Derleme hatası oluşur'], 'C++\'ta işlevler varsayılan olarak statik bağlanır; virtual olmadığı için çağrı işaretçinin türüne göre Taban sürümüne bağlanır.'),
  ('C++ derleyicilerinin sanal işlev çağrılarını çalışma anında doğru sınıfın işlevine yönlendirmek için yaygın olarak kullandığı yapıya ne ad verilir?', 'Sanal işlev tablosu', ['Sembol tablosu', 'Yığın çerçevesi', 'Karma tablosu'], 'Sanal işlevi olan her sınıf için işlev adreslerini tutan bir tablo oluşturulur; her nesne bu tabloya bir işaretçi taşır ve çağrı bu tablo üzerinden yapılır.'),
  ('C++\'ta virtual double alan() = 0; biçimindeki bildirim ne anlama gelir?', 'Saf sanal işlevdir; sınıfı soyut yapar', ['İşlevin varsayılan dönüş değeri 0\'dır', 'İşlev hiçbir zaman çağrılamaz ve silinir', 'İşlev yalnız sabit nesnelerde çalışır'], '= 0 eki işlevi saf sanal yapar; en az bir saf sanal işlevi olan sınıftan nesne oluşturulamaz ve alt sınıfların bu işlevi tanımlaması gerekir.'),
  ('C#\'ta bir üst sınıf yönteminin alt sınıfta çok biçimli olarak geçersiz kılınabilmesi için hangi anahtar sözcük çifti gerekir?', 'Üst sınıfta virtual, alt sınıfta override', ['Üst sınıfta abstract, alt sınıfta new', 'Üst sınıfta static, alt sınıfta virtual', 'Üst sınıfta sealed, alt sınıfta override'], 'C#\'ta yöntemler varsayılan olarak sanal değildir. Üst yöntem virtual (ya da abstract) olmalı, alt sınıfta override yazılmalıdır; new ise geçersiz kılmak yerine yöntemi gizler.'),
  ('Python\'da bir sınıfta önce def alan(self, r) sonra def alan(self, en, boy) tanımlanırsa ne olur?', 'İkinci tanım birincinin yerini alır', ['İki yöntem aşırı yüklenmiş olarak kullanılır', 'Sınıf tanımı SyntaxError verir', 'Çağrıda ilk tanım öncelikli olur'], 'Python yöntem adlarını sınıfın ad alanındaki bir sözlükte tutar; aynı ada yapılan ikinci atama ilkinin üzerine yazılır. Python\'da klasik aşırı yükleme yoktur.'),
  ('Aşırı yükleme ve geçersiz kılma, çok biçimlilik açısından genellikle nasıl sınıflandırılır?', 'Aşırı yükleme derleme zamanı, geçersiz kılma çalışma zamanı çok biçimliliğidir', ['İkisi de çalışma zamanı çok biçimliliğidir', 'Aşırı yükleme çalışma zamanı, geçersiz kılma derleme zamanı çok biçimliliğidir', 'İkisi de yalnız kalıtım olmadan kullanılabilir'], 'Aşırı yüklenmiş yöntemlerden hangisinin çağrılacağı derlemede, geçersiz kılınmış bir yöntemin hangi sürümünün çalışacağı ise nesnenin gerçek türüne göre çalışmada belirlenir.'),
  ('Java\'da static olmayan, private olmayan ve final olmayan örnek yöntemleri için hangisi doğrudur?', 'Varsayılan olarak dinamik bağlanırlar', ['Yalnız virtual yazılırsa dinamik bağlanırlar', 'Her zaman derleme zamanında bağlanırlar', 'Alt sınıflarda yeniden tanımlanamazlar'], 'C++ ve C#\'tan farklı olarak Java\'da bu tür yöntemler kendiliğinden sanaldır; alt sınıf onları geçersiz kılabilir ve çağrı nesnenin gerçek türüne göre çözülür.'),
  ('Java\'da Kedi, Hayvan\'ın alt sınıfıdır. Hayvan h = new Kedi(); ve Kedi k = (Kedi) h; satırlarındaki dönüşümler için hangisi doğrudur?', 'İlki örtük yukarı, ikincisi açık aşağı dönüşümdür', ['İkisi de örtük yapılabilir', 'İlki açık aşağı dönüşüm, ikincisi örtük yukarı dönüşümdür', 'İkisi de derleme hatası verir'], 'Alt türden üst türe dönüşüm (upcasting) her zaman güvenli olduğundan örtüktür. Üst türden alt türe dönüşüm (downcasting) başarısız olabileceği için açıkça yazılmalıdır.'),
  ('Java\'da Hayvan h = new Kedi(); Kopek k = (Kopek) h; satırları çalıştırılırsa ne olur?', 'Çalışma anında ClassCastException fırlatılır', ['Derleme hatası oluşur', 'k değişkeni null olur', 'Kedi nesnesi alanlarıyla birlikte Kopek nesnesine dönüştürülür'], 'Derleyici Hayvan\'dan Kopek\'e dönüşümü olası gördüğü için kabul eder; ancak çalışma anında nesnenin gerçekte Kedi olduğu anlaşılınca dönüşüm reddedilir.'),
  ('Java\'da Hayvan h = new Kedi(); tanımlıdır ve tirmala() yöntemi yalnız Kedi sınıfında vardır. h.tirmala(); yazılırsa ne olur?', 'Derleme hatası oluşur', ['Kedi\'nin tirmala() yöntemi çalışır', 'Çalışma anında istisna fırlatılır', 'Hiçbir şey olmaz, çağrı yok sayılır'], 'Derleyici hangi yöntemlerin çağrılabileceğine değişkenin bildirilen türüne bakarak karar verir. Hayvan türünde tirmala() olmadığından çağrı derlenmez; önce Kedi\'ye dönüştürmek gerekir.'),
  ('Java\'da soyut (abstract) bir sınıfın yapıcısı olabilir mi?', 'Evet; alt sınıf nesneleri oluşturulurken çağrılır', ['Hayır; soyut sınıflar yapıcı içeremez', 'Evet; ancak yalnız new ile programcı tarafından doğrudan çağrılır', 'Hayır; derleyici yapıcıyı otomatik siler'], 'Soyut sınıftan doğrudan nesne oluşturulamaz, ama ortak alanları başlatmak için yapıcı yazılabilir; bu yapıcı alt sınıfın yapıcısındaki super(...) çağrısıyla çalışır.'),
  ('Java\'daki soyut sınıflarla ilgili hangisi doğrudur?', 'Gövdeli yöntemler ve örnek alanları da içerebilir', ['Yalnız gövdesiz soyut yöntemler ve sabitler içerebilir', 'Hiç alan içeremez', 'Bir arayüzü uygulayamaz'], 'Soyut sınıf, gövdesi olan somut yöntemler, alanlar ve yapıcılar içerebilir; yalnız en az bir eksik parçayı alt sınıflara bırakmak için tasarlanır.'),
  ('Java\'da Sekil soyut sınıfının iki soyut yöntemi var. Daire extends Sekil sınıfı bunlardan yalnız birini gerçekleştiriyor. Daire için hangisi geçerlidir?', 'Daire de abstract bildirilmezse derleme hatası oluşur', ['Eksik yöntem otomatik olarak boş gövdeyle eklenir', 'Daire\'den nesne oluşturulabilir, eksik yöntem çağrılınca hata verir', 'Eksik yöntem Sekil\'deki gövdeyle çalışır'], 'Soyut yöntemlerin hepsini gerçekleştirmeyen bir alt sınıf hâlâ eksik olduğundan kendisi de soyut olmalıdır; aksi halde derleyici hata verir.'),
  ('Java\'da bir yöntemin hem abstract hem de final olarak bildirilmesi neden derleme hatası verir?', 'abstract geçersiz kılınmayı gerektirir, final bunu yasaklar', ['final yöntemler yalnız arayüzlerin içinde tanımlanıp kullanılabilir', 'abstract yöntemlerin dönüş türü olamaz', 'İki anahtar sözcük aynı satırda yazılamaz'], 'Soyut yöntemin bir gövde kazanabilmesi için alt sınıfta geçersiz kılınması şarttır; final ise geçersiz kılmayı yasakladığından ikisi birbiriyle çelişir.'),
  ('Python\'da ABC\'den türeyen Sekil sınıfında @abstractmethod ile alan() bildirilmiştir. Bu yöntemi tanımlamayan Ucgen(Sekil) sınıfından Ucgen() ile nesne oluşturulmak istenirse ne olur?', 'TypeError fırlatılır', ['Nesne oluşur, alan() çağrılınca None döner', 'Nesne oluşur, uyarı yazdırılır', 'SyntaxError oluşur'], 'abc modülü, soyut yöntemleri tamamlanmamış sınıfların örneklenmesini engeller; nesne oluşturma anında TypeError fırlatılır.'),
  ('Java\'da bir arayüzde int MAKS = 10; biçiminde tanımlanan alan örtük olarak hangi niteliklere sahiptir?', 'public, static ve final', ['private ve static', 'protected, final ve transient', 'Yalnız public'], 'Arayüzlerde bildirilen alanlar her zaman public static final kabul edilir; yani arayüze ait değiştirilemez sabitlerdir.'),
  ('Java 8 ile arayüzlere default yöntemlerin eklenmesinin başlıca nedeni neydi?', 'Mevcut arayüzlere, uygulayan sınıfları bozmadan yöntem eklemek', ['Arayüzlerin doğrudan örneklenebilmesini sağlamak', 'Arayüzlere örnek alanları ekleyebilmek', 'Sınıfların aynı anda birden çok sınıftan kalıtım alabilmesini sağlamak'], 'Örneğin Collection arayüzüne stream() eklenirken binlerce sınıfın derlenememesi istenmedi; default yöntem bir varsayılan gövde sunarak geriye uyumluluğu korur.'),
  ('Java\'da yalnız tek bir soyut yöntemi bulunan ve lambda ifadeleriyle gerçekleştirilebilen arayüzlere ne ad verilir?', 'İşlevsel arayüz', ['İşaretleyici arayüz', 'Soyut arayüz', 'İç arayüz'], 'Runnable ya da Comparator gibi tek soyut yöntemli arayüzler işlevsel arayüzdür; @FunctionalInterface ek açıklamasıyla da işaretlenebilir.'),
  ('Java\'da Serializable ve Cloneable gibi hiçbir yöntem içermeyen, yalnız bir sınıfın belirli bir yeteneğe sahip olduğunu bildiren arayüzlere ne ad verilir?', 'İşaretleyici (marker) arayüz', ['İşlevsel arayüz', 'Soyut sınıf', 'Genel türlü (generic) parametreli arayüz'], 'İşaretleyici arayüzler davranış tanımlamaz; çalışma ortamı ya da kütüphaneler, nesnenin bu arayüzü uygulayıp uygulamadığına bakarak işlem yapar.'),
  ('Java\'da Comparable, Runnable ve Iterable gibi arayüz adlarının çoğunun \'-able\' ile bitmesi arayüzlerin hangi kullanımını yansıtır?', 'Farklı sınıflara ortak bir yetenek kazandırmayı', ['Bir sınıfın türetildiği tek üst sınıfı açıkça belirlemeyi', 'Bir sınıfın alanlarını gizlemeyi', 'Nesneleri bellekte sabitlemeyi'], 'Arayüzler çoğunlukla \'karşılaştırılabilir\', \'çalıştırılabilir\' gibi birbiriyle akraba olmayan sınıfların da paylaşabileceği yetenekleri tanımlar.'),
  ('Java\'da List<String> liste = new ArrayList<>(); yazmak, ArrayList<String> liste = new ArrayList<>(); yazmaya göre hangi yararı sağlar?', 'Uygulama sınıfı az değişiklikle başkasıyla değiştirilebilir', ['Liste daha az bellek kullanır', 'Listeye yalnız String eklenebilir', 'Liste öğeleri eklendikçe otomatik olarak sıralı tutulur ve korunur'], 'Değişkeni arayüz türüyle bildirmek (\'arayüze göre programla\') kodu somut sınıfa bağlamaz; örneğin sonradan LinkedList\'e geçmek için yalnız tek satır değişir.'),
  ('Java\'da aşağıdaki bildirimlerden hangisi geçerlidir? (A ve B sınıf, I ve J arayüzdür.)', 'class X extends A implements I, J', ['class X extends A, B', 'class X implements I, J extends A, B', 'interface K implements I, J'], 'Bir sınıf tek bir sınıftan extends ile türer, ardından birden çok arayüzü implements ile uygular. Arayüzler başka arayüzleri implements ile değil extends ile genişletir.'),
  ('Yigin<T> gibi bir sınıfın, T yerine hangi tür konursa konsun aynı kodla çalışması hangi çok biçimlilik türüne örnektir?', 'Parametrik çok biçimlilik', ['Alt tür çok biçimliliği', 'Geçici (ad hoc) çok biçimlilik', 'Zorlama (coercion) çok biçimliliği'], 'Parametrik çok biçimlilikte kod bir tür parametresi üzerinden yazılır ve her türle aynı biçimde çalışır; jenerikler ve şablonlar bunun örnekleridir.'),
  ('Bir dilde + işlecinin sayılarda toplama, metinlerde birleştirme yapması gibi, aynı adın her tür için ayrı bir tanıma bağlanması hangi çok biçimlilik türüdür?', 'Geçici (ad hoc) çok biçimlilik', ['Parametrik çok biçimlilik', 'Alt tür çok biçimliliği', 'Satır (row) çok biçimliliği'], 'Ad hoc çok biçimlilikte aynı ad farklı türler için ayrı ayrı yazılmış gerçekleştirimlere bağlanır; aşırı yükleme ve işleç aşırı yüklemesi bu türdendir.'),
  ('Java\'da List<int> sayilar = new ArrayList<>(); bildirimi neden derlenmez?', 'Tür argümanları ilkel tür olamaz; Integer kullanılmalıdır', ['int türü listeye hiç eklenemez', 'Listeler yalnız String tutabilir', 'Elmas işleci <> ilkel int türüyle hiçbir biçimde birlikte kullanılamaz'], 'Java jenerikleri yalnız başvuru türleriyle çalışır. İlkel türler için Integer, Double gibi sarmalayıcı sınıflar kullanılır ve otomatik kutulama dönüşümü sağlar.'),
  ('Java\'da static <T extends Comparable<T>> T enBuyuk(List<T> liste) yöntemindeki \'extends Comparable<T>\' kısıtının amacı nedir?', 'Yöntem içinde öğelerin compareTo ile karşılaştırılabilmesi', ['T yerine yalnız Comparable sınıfının kendisinin yazılabilmesini sağlamak', 'Listenin değiştirilemez hale getirilmesi', 'Yöntemin yalnız sayılarla çağrılabilmesi'], 'Sınırlı tür parametresi, T yerine yalnız Comparable uygulayan türlerin konabileceğini garanti eder; böylece derleyici compareTo çağrısına izin verir.'),
  ('Java\'da jenerik bir yöntem bildirilirken tür parametresi listesi (ör. <T>) nereye yazılır?', 'Dönüş türünün hemen önüne', ['Yöntem adının hemen sonrasına', 'Parametre listesinin içine', 'Yöntem gövdesinin ilk satırına'], 'Örneğin public static <T> T ilk(List<T> liste) bildiriminde <T> belirleyicilerden sonra, dönüş türünden önce yazılır.'),
  ('Java\'da kullanıcının kendi sınıfı için + işlecini yeniden tanımlaması mümkün müdür?', 'Hayır; Java buna izin vermez', ['Evet; sınıfa operator+ adlı bir yöntem yazılarak yapılır', 'Evet; sınıfa __add__ adlı bir yöntem yazılarak yapılır', 'Yalnız soyut sınıflarda yapılabilir'], 'Java tasarımcıları okunabilirlik gerekçesiyle kullanıcı tanımlı işleç aşırı yüklemesini dile almadı; + yalnız sayılar ve String birleştirme için yerleşik olarak çok anlamlıdır.'),
  ('Python\'da bir sınıfta hem __str__ hem __repr__ tanımlanmışsa print(nesne) hangisini kullanır ve __repr__ hangi amaçla düşünülmüştür?', 'print __str__ kullanır; __repr__ geliştiriciye yönelik kesin gösterimdir', ['print __repr__ kullanır; __str__ yalnız dosyaya yazarken kullanılır', 'İkisi aynı işi yapar; Python her çağrıda rastgele birini seçip kullanır', 'print ikisini art arda yazdırır'], '__str__ kullanıcıya okunaklı metin, __repr__ ise hata ayıklamaya yönelik, mümkünse nesneyi yeniden oluşturmaya yetecek gösterim içindir.'),
  ('Python\'da kendi Ogrenci nesnelerinden oluşan bir listenin sorted(liste) ile doğrudan sıralanabilmesi için sınıfta en azından hangi yöntem tanımlanmalıdır?', '__lt__', ['__sort__', '__cmp__', '__order__'], 'sorted ve list.sort öğeleri < işleciyle karşılaştırır; bu yüzden __lt__ tanımlamak yeterlidir. Python 3\'te __cmp__ artık kullanılmaz.'),
  ('Python\'da bir sınıfa __getitem__ yöntemi eklenmesi nesneye hangi yeteneği kazandırır?', 'nesne[i] biçiminde köşeli parantezle erişimi', ['nesne.i biçiminde nitelik erişimini', 'nesne(i) biçiminde bir işlev gibi doğrudan çağrılabilmeyi', 'nesne + i biçiminde toplamayı'], 'Köşeli parantezli erişim __getitem__ çağrısına dönüşür; bu yöntem sıfırdan başlayan tamsayılarla çalışıyorsa nesne for döngüsünde de gezilebilir.'),
  ('Python\'da Carpici sınıfının nesnesi c = Carpici(3) olarak oluşturulmuş ve c(5) çağrısı 15 döndürüyor. Bunu sağlayan özel yöntem hangisidir?', '__call__', ['__init__', '__invoke__', '__run__'], 'Bir sınıfa __call__ tanımlanırsa nesneleri işlev gibi çağrılabilir; c(5) ifadesi c.__call__(5) olarak yürütülür.'),
  ('Python\'da "elma" in sepet ifadesinin kendi Sepet sınıfı için özel bir mantıkla çalışması isteniyor. Hangi yöntem tanımlanmalıdır?', '__contains__', ['__in__', '__has__', '__find__'], 'in işleci önce nesnenin __contains__ yöntemini arar; bu yöntem yoksa __iter__ ya da __getitem__ ile öğeler tek tek gezilerek karşılaştırılır.'),
  ('Python\'da kendi yazdığı bir yineleyici sınıfının __next__ yöntemi, verilecek öğe kalmadığında ne yapmalıdır?', 'StopIteration istisnası fırlatmalıdır', ['None döndürmelidir', 'Boş bir liste döndürmelidir', 'Yineleyiciyi sıfırlayıp ilk öğeden baştan başlatmalıdır'], 'for döngüsü __next__ çağrılarını StopIteration yakalanana kadar sürdürür; None geçerli bir öğe olabileceği için bitişi belirtmez.'),
  ('Java\'da iki nesnenin hashCode değerlerinin aynı çıkması için hangisi doğrudur?', 'equals ile eşit olduklarını kesinleştirmez', ['equals ile kesinlikle eşit oldukları anlamına gelir', 'İki nesnenin aynı nesne olduğunu gösterir', 'Sözleşmeye göre hiç olmaması gereken bir durumdur'], 'Sözleşme yalnız eşit nesnelerin aynı karma değeri taşımasını ister. Tersi gerekmez; farklı nesnelerin aynı değeri alması çakışma olarak kabul edilir.'),
  ('Java equals sözleşmesinde \'a.equals(b) true ise b.equals(a) da true olmalıdır\' kuralı hangi özelliktir?', 'Simetri', ['Yansıma', 'Geçişlilik', 'Tutarlılık'], 'equals yansımalı (a.equals(a)), simetrik, geçişli ve tutarlı olmalı; ayrıca a.equals(null) false döndürmelidir.'),
  ('Java\'da Comparable ve Comparator arayüzleri arasındaki temel fark hangisidir?', 'Comparable doğal sırayı sınıf içinde, Comparator başka sırayı dışarıda tanımlar', ['Comparable yalnız sayısal alanlar, Comparator yalnız metin alanları için kullanılabilir', 'Comparator sınıfın içinde, Comparable ayrı bir sınıfta yazılmak zorundadır', 'İkisi aynıdır; Comparator eski sürümlerden kalmadır'], 'Comparable\'ı uygulayan sınıf compareTo ile tek bir doğal sıra belirler. Comparator ise ada göre, yaşa göre gibi istenen kadar farklı sıralamayı sınıfı değiştirmeden tanımlamayı sağlar.'),
  ('Java\'da toString yöntemini geçersiz kılmayan bir Kitap nesnesi yazdırıldığında çıktı hangi biçime benzer?', 'Kitap@1b6d3586', ['Kitap{ad=..., yazar=...}', 'Kitap nesnesi', 'null'], 'Object.toString sınıf adını, @ işaretini ve karma değerin onaltılık yazımını döndürür; alanları göstermez.'),
  ('Python\'da kendi Kesir sınıfının nesneleri if kesir: koşulunda değeri sıfır olduğunda yanlış sayılsın isteniyor. Hangi yöntem tanımlanmalıdır?', '__bool__', ['__truth__', '__zero__', '__test__'], 'Bir nesnenin doğruluk değeri __bool__ ile belirlenir; bu yöntem yoksa __len__ bakılır, ikisi de yoksa nesne her zaman doğru sayılır.'),
  ('Python\'da A\'nın f() yöntemi "A", B(A) sınıfınınki "B", C(A) sınıfınınki "C" döndürüyor; class D(B, C): pass tanımlı. D().f() ne döndürür?', '"B"', ['"C"', '"A"', 'TypeError'], 'D\'nin yöntem çözümleme sırası D, B, C, A, object\'tir. f önce D\'de aranır, bulunamayınca ilk üst sınıf olan B\'de bulunur.'),
  ('Nesne yönelimli programlamada \'mixin\' sınıfı en iyi nasıl tanımlanır?', 'Başka sınıflara ek yetenek katmak için karıştırılan küçük sınıf', ['Programdaki bütün sınıfların doğrudan ya da dolaylı türediği kök sınıf', 'Yalnız statik yöntemlerden oluşan yardımcı sınıf', 'Nesne oluşturmayı üstlenen fabrika sınıfı'], 'Mixin\'ler örneğin JSON\'a dönüştürme ya da günlük tutma gibi tek bir yeteneği paketler ve çoklu kalıtımla başka sınıflara eklenir; kendi başlarına anlamlı bir varlık temsil etmezler.'),
  ('Rust dilinde sınıf kalıtımı bulunmaz. Farklı türlere ortak davranış kazandırmak için başlıca hangi yapı kullanılır?', 'Trait', ['Mixin modülü', 'Soyut sınıf', 'Prototip zinciri'], 'Rust\'ta türler struct ve enum ile tanımlanır; ortak davranış trait\'lerde bildirilir ve impl Trait for Tur bloklarıyla her tür için gerçekleştirilir.'),
  ('Python\'da issubclass(bool, int) ifadesi True döner. Bu sonuç neyi gösterir?', 'bool sınıfı int sınıfından türetilmiştir', ['bool ve int aynı sınıfın iki adıdır', 'Python her sınıfı int\'ten türetir', 'issubclass yalnız değer karşılaştırması yapar'], 'Python\'da True ve False, sırasıyla 1 ve 0 değerli int alt sınıfı nesneleridir; bu yüzden True + True ifadesi 2 verir.'),
  ('Bir Oyuncu sınıfında hareket biçimi içteki bir HareketStratejisi nesnesinde tutuluyor; oyun sırasında oyuncu.setHareket(new Ucma()) ile değiştirilebiliyor. Kalıtımla Kosan ve Ucan alt sınıfları yazmaya göre bu tasarımın üstünlüğü nedir?', 'Davranış çalışma anında aynı nesne üzerinde değiştirilebilir', ['Daha az sayıda nesne oluşturulmasını garanti eder', 'Derleyicinin tür hatalarını çok daha erken ve eksiksiz yakalamasını sağlar', 'Oyuncu sınıfını soyut sınıfa dönüştürür'], 'Kalıtımla seçilen davranış nesne oluşturulurken sabitlenir; bileşimde ise içteki bileşen değiştirilerek aynı nesnenin davranışı çalışırken değiştirilebilir.'),
  ('Python\'da import copy; a = [[1, 2], [3]]; b = copy.copy(a); b[0].append(9) çalıştırıldıktan sonra a[0] nedir?', '[1, 2, 9]', ['[1, 2]', '[9]', '[1, 2, [9]]'], 'copy.copy sığ kopya yapar: dış liste yenidir ama içteki listeler aynı nesnelerdir. b[0] ile a[0] aynı listeyi gösterdiğinden değişiklik a\'da da görülür.'),
  ('Bir nesnenin sığ kopyası (shallow copy) alınırken nesnenin başka nesneleri gösteren alanları için ne olur?', 'Başvurular kopyalanır; iki nesne aynı iç nesneleri paylaşır', ['Gösterilen iç nesnelerin de yeni kopyaları oluşturulur ve bağlanır', 'Başvuru alanları kopyaya hiç aktarılmaz, null bırakılır', 'İç nesneler özgün nesneden silinip kopyaya taşınır'], 'Sığ kopya yalnız en dış nesneyi çoğaltır; alanlardaki başvurular aynen aktarıldığı için iç nesneler ortak kalır. Derin kopya ise iç nesneleri de çoğaltır.'),
  ('C++\'ta Nokta sınıfı için kopya yapıcının (copy constructor) olağan imzası hangisidir?', 'Nokta(const Nokta& diger)', ['Nokta(Nokta* diger)', 'Nokta copy(Nokta diger)', 'void Nokta(const Nokta diger)'], 'Kopya yapıcı aynı türden bir nesneye sabit başvuru alır. Parametre değerle alınsaydı, argümanı kopyalamak için yine kopya yapıcı çağrılır ve sonsuz özyineleme oluşurdu.'),
  ('Değişmez nesnelerin, değiştirilebilir nesnelere göre sağladığı yararlardan biri hangisidir?', 'Savunmacı kopya almadan güvenle paylaşılabilmeleri', ['Her işlemde daha az nesne oluşturulmasının garanti olması', 'Alanlarının çalışma anında serbestçe değiştirilebilmesi', 'Kalıtımla sınırsız biçimde genişletilebilmeleri'], 'Değişmez bir nesne hiç değişmeyeceği için birden çok yerde aynı örnek paylaşılabilir, önbelleğe alınabilir ve sözlük anahtarı olarak güvenle kullanılabilir.'),
  ('Java\'da LocalDate d = LocalDate.of(2024, 1, 1); d.plusDays(1); System.out.println(d); kodu ne yazdırır?', '2024-01-01', ['2024-01-02', 'null', 'Derleme hatası'], 'LocalDate değişmezdir; plusDays yeni bir nesne döndürür, özgün nesneyi değiştirmez. Dönen değer bir değişkene atanmadığı için d ilk tarihi göstermeye devam eder.'),
  ('Java\'da String sınıfından extends ile yeni bir sınıf türetilememesinin doğrudan nedeni nedir?', 'String sınıfı final olarak bildirilmiştir', ['String sınıfı soyut (abstract) bir sınıftır', 'String bir arayüzdür, sınıf değildir', 'String sınıfının yapıcısı yoktur'], 'final sınıflardan kalıtım alınamaz. String\'in final olması, değişmezliğinin alt sınıflar aracılığıyla bozulmasını engeller.'),
  ('C#\'ta bir sınıftan kalıtım alınmasını engellemek için kullanılan anahtar sözcük hangisidir?', 'sealed', ['final', 'static', 'readonly'], 'C#\'ta sealed sınıflar türetilemez; Java\'daki final sınıfın karşılığıdır. readonly ise alanlar için kullanılır.'),
  ('Kotlin\'de bir sınıftan başka sınıfların türetilebilmesi için sınıf nasıl bildirilmelidir?', 'open anahtar sözcüğüyle', ['abstract olmadan, hiçbir şey eklemeden', 'public anahtar sözcüğüyle', 'inheritable ek açıklamasıyla'], 'Kotlin\'de sınıflar ve yöntemler varsayılan olarak final\'dır; kalıtıma açmak için open (ya da abstract) ile bildirilmeleri gerekir.'),
  ('Java\'da static olarak tanımlanmış iç içe (nested) bir sınıf için hangisi doğrudur?', 'Dış sınıfın örnek alanlarına bir nesne olmadan erişemez', ['Yalnız dış sınıfın nesnesi üzerinden oluşturulabilir', 'Dış sınıfın bütün örnek alanlarına doğrudan erişir', 'Kendi alanları ve yöntemleri olamaz'], 'Statik iç içe sınıf bir dış nesneye bağlı değildir; dış sınıfın statik üyelerine erişebilir ama örnek alanları için bir dış nesne başvurusuna ihtiyaç duyar.'),
  ('Java\'da statik olmayan bir iç sınıfın kodu, dış sınıfın private alanlarına erişebilir mi?', 'Evet, doğrudan erişebilir', ['Hayır, yalnız public alanlara erişebilir', 'Yalnız getter yöntemleri varsa erişebilir', 'Yalnız alanlar static ise erişebilir'], 'İç sınıf dış sınıfın bir parçası sayılır; bu yüzden dış sınıfın private üyeleri de dahil bütün üyelerine erişebilir.'),
  ('JavaScript\'te bir nesnede bulunmayan bir özelliğe erişilmek istendiğinde arama nasıl sürer?', 'Nesnenin prototip zincirinde yukarı doğru aranır', ['Hemen TypeError fırlatılır', 'Nesnenin sınıfının statik alanlarına bakılır', 'Genel (global) değişkenlerde aranır'], 'JavaScript\'te her nesnenin bir prototipi vardır; özellik nesnede bulunamazsa prototipinde, sonra onun prototipinde aranır ve zincirin sonunda bulunamazsa undefined döner.'),
  ('JavaScript\'te const kedi = Object.create(hayvan); satırı ne yapar?', 'Prototipi hayvan olan yeni bir nesne oluşturur', ['hayvan nesnesinin derin bir kopyasını oluşturur', 'hayvan nesnesini kedi adıyla yeniden adlandırır', 'hayvan adlı bir sınıftan kedi örneğini türetir'], 'Object.create, verilen nesneyi yeni nesnenin prototipi yapar; kedi\'de olmayan özellikler hayvan üzerinden okunur, ama hayvan kopyalanmaz.'),
  ('JavaScript\'e ES2015 (ES6) ile gelen class sözdizimi için hangisi doğrudur?', 'Prototip tabanlı modelin üzerine kurulmuş daha okunaklı bir yazımdır', ['Prototip mekanizmasını dilden tamamen kaldırmıştır', 'Java\'daki gibi derleme zamanında tür denetimi getirmiştir', 'Yalnız Node.js ortamında çalışan ayrı bir modeldir'], 'class sözdizimi yine prototipler üzerinden çalışır; sınıf yöntemleri yapıcı işlevin prototype nesnesine eklenir.'),
  ('JavaScript\'te function Kedi() {} tanımlanıp const k = new Kedi(); çalıştırıldıktan sonra Kedi.prototype.miyavla = function() { return 42; }; yazılırsa k.miyavla() ne döndürür?', '42', ['undefined', 'TypeError', 'NaN'], 'k\'nin prototipi Kedi.prototype nesnesidir. Bu nesneye sonradan eklenen yöntem, arama prototip zincirinden yapıldığı için önceden oluşturulmuş nesnelerde de kullanılabilir.'),
  ('Smalltalk\'ta 3 + 4 ifadesi nasıl yorumlanır?', '3 nesnesine argümanı 4 olan + mesajı gönderilir', ['Derleyici bunu ilkel bir makine toplamasına çevirir, nesne yoktur', '+ adlı genel bir işlev iki sayıyla çağrılır', '4 nesnesi 3 nesnesinden kalıtım alır'], 'Smalltalk\'ta sayılar da dahil her şey nesnedir ve bütün hesaplama mesaj gönderimiyle yapılır; + de 3 nesnesinin yanıtladığı bir mesajdır.'),
  ('Smalltalk\'ta ve Python\'da sınıfların kendileri de nesnedir. Bir sınıfın örneği olduğu sınıfa ne ad verilir?', 'Metasınıf', ['Üst sınıf', 'Soyut sınıf', 'Arayüz sınıfı'], 'Sınıfların sınıfına metasınıf denir; örneğin Python\'da sınıflar varsayılan olarak type metasınıfının örnekleridir ve sınıf oluşturma süreci metasınıfla özelleştirilebilir.'),
  ('Python\'da class Kisi: pass tanımlandıktan sonra type(Kisi) ifadesi ne döndürür?', '<class \'type\'>', ['<class \'object\'>', '<class \'Kisi\'>', '<class \'class\'>'], 'Kisi sınıfının kendisi type metasınıfından oluşturulmuş bir nesnedir; Kisi() ile oluşturulan nesnelerin türü ise Kisi\'dir.'),
  ('Python\'da niteliğin adı çalışma anında bir değişkende metin olarak tutuluyorsa (ad = "yas"), bu niteliğin değerini nesneden okumak için hangisi kullanılır?', 'getattr(nesne, ad)', ['nesne.ad', 'nesne[ad]', 'type(nesne).ad'], 'getattr ikinci argümandaki metne karşılık gelen niteliği döndürür. nesne.ad yazmak ise doğrudan \'ad\' adlı niteliği arar.'),
  ('Python\'da bir nesnenin örnek niteliklerinin ad-değer çiftleri olarak saklandığı sözlük hangisidir?', 'nesne.__dict__', ['nesne.__slots__', 'nesne.__class__', 'nesne.__mro__'], 'Sıradan Python nesneleri örnek niteliklerini __dict__ sözlüğünde tutar; bu yüzden çalışma anında yeni nitelik eklenebilir.'),
  ('Çalışmakta olan bir programda, var olan bir sınıfın yöntemini kaynak koduna dokunmadan yenisiyle değiştirme uygulamasına (ör. Python\'da Sinif.yontem = yeni_islev) gayriresmî olarak ne ad verilir?', 'Maymun yaması (monkey patching)', ['Ördek tiplemesi (duck typing)', 'Kod tekrarı (copy paste)', 'Ağaç sarsma (tree shaking)'], 'Monkey patching, dinamik dillerde sınıfları ya da modülleri çalışma anında değiştirmektir; testlerde işe yarasa da kodun izlenmesini zorlaştırır.'),
  ('Her yeni isteğe bağlı parametre için bir öncekini çağıran yeni bir yapıcı eklenmesiyle oluşan Pizza(int), Pizza(int, bool), Pizza(int, bool, bool)... zincirine ne ad verilir?', 'Teleskopik yapıcı (telescoping constructor)', ['Yapıcı yetkilendirmesi (constructor delegation)', 'Kopya yapıcı zinciri (copy chain)', 'Yapıcı enjeksiyonu (constructor injection)'], 'Teleskopik yapıcılarda hangi konumdaki true\'nun neyi anlattığı okunamaz hale gelir; Builder kalıbı bu sorunun yaygın çözümüdür.'),
  ('Bir oyunda yüklenmesi pahalı olan bir canavar nesnesinin, her seferinde sıfırdan oluşturulmak yerine hazır bir örneğinin kopyalanarak yeni canavarlar üretilmesi hangi kalıba uyar?', 'Prototype', ['Builder', 'Singleton', 'Facade'], 'Prototype kalıbında yeni nesneler, var olan bir örneğin klonlanmasıyla oluşturulur; istemci somut sınıfı bilmek zorunda kalmaz.'),
  ('Bir arayüz kütüphanesi Windows ve macOS için birbiriyle uyumlu Dugme, Pencere ve Menu nesnelerini aileler halinde üretmek istiyor; istemci hangi ailenin kullanıldığını bilmeyecek. En uygun kalıp hangisidir?', 'Abstract Factory', ['Prototype', 'Decorator', 'Iterator'], 'Soyut fabrika, birbiriyle ilişkili nesne ailelerini somut sınıflarını belirtmeden oluşturan bir arayüz sunar; WindowsFabrikasi ve MacFabrikasi bu arayüzü uygular.'),
  ('Singleton kalıbının sık eleştirilmesinin başlıca gerekçesi hangisidir?', 'Gizli genel durum yaratması ve birim testini zorlaştırması', ['Bellekte gereğinden çok sayıda aynı türden nesne oluşmasına yol açması', 'Kalıtımı zorunlu kılması', 'Yalnız C++ dilinde uygulanabilmesi'], 'Singleton\'a her yerden erişilebildiği için bağımlılıklar koddan görünmez; testlerde sahte bir nesneyle değiştirmek ve testleri birbirinden yalıtmak zorlaşır.'),
  ('Veritabanı bağlantıları gibi oluşturulması pahalı nesnelerin kullanımdan sonra yok edilmeyip bir havuzda tutulması ve yeniden kullanılması hangi kalıptır?', 'Nesne havuzu (Object Pool)', ['Prototype (ön örnek)', 'Memento (hatıra) kalıbı', 'Facade'], 'Nesne havuzu, sınırlı sayıda nesneyi önceden ya da gerektikçe oluşturur; istemciler nesneyi havuzdan alır, işi bitince geri bırakır.'),
  ('Bir resim görüntüleyici, büyük fotoğrafları ancak ekranda gösterilecekleri an diskten yüklüyor; o zamana kadar aynı arayüzü taşıyan hafif bir yer tutucu nesne kullanıyor. Bu hangi kalıptır?', 'Proxy (vekil)', ['Adapter (uyarlayıcı)', 'Bridge (köprü)', 'Builder (kurucu)'], 'Vekil, gerçek nesneyle aynı arayüzü sunup ona erişimi denetler; burada sanal vekil pahalı yüklemeyi gerçekten gerekene kadar erteler.'),
  ('Bir metin düzenleyicide milyonlarca karakter nesnesi var; yazı tipi ve boyut gibi ortak bilgiler paylaşılan az sayıda nesnede tutulup her karakter yalnız konumunu saklıyor. Bellek tasarrufu sağlayan bu kalıp hangisidir?', 'Flyweight (sinek siklet)', ['Composite (bileşik nesne)', 'Prototype (ön örnek)', 'Memento (hatıra)'], 'Flyweight, nesnelerin paylaşılabilir iç durumunu ortak nesnelerde, değişen dış durumunu ise kullanıcı tarafta tutarak çok sayıda küçük nesnenin bellek maliyetini düşürür.'),
  ('Bir metin düzenleyicide her kullanıcı işlemi calistir() ve geriAl() yöntemleri olan bir nesne olarak saklanıyor; bu nesneler bir yığında tutularak \'geri al\' özelliği sağlanıyor. Bu hangi kalıptır?', 'Command (komut)', ['Observer (gözlemci)', 'Strategy (strateji)', 'Adapter (uyarlayıcı)'], 'Command kalıbı bir isteği nesneye dönüştürür; böylece istekler sıraya konabilir, kaydedilebilir ve geri alınabilir.'),
  ('Bir İcecek soyut sınıfının hazirla() yöntemi suyu kaynat, demle, bardağa dök, eklenti koy adımlarını sabit sırayla çağırıyor; demle() ve eklentiKoy() adımlarını Cay ve Kahve alt sınıfları kendine göre yazıyor. Bu yapı hangi kalıptır?', 'Template Method (şablon yöntem)', ['Strategy (strateji)', 'Builder (kurucu)', 'Chain of Responsibility'], 'Şablon yöntem, algoritmanın iskeletini üst sınıfta sabitler ve bazı adımları alt sınıflara bırakır; adımların sırası alt sınıflarca değiştirilemez.'),
  ('Bir sipariş nesnesinin davranışı \'Hazırlanıyor\', \'Kargoda\' ve \'Teslim edildi\' aşamalarına göre değişiyor. Uzun if-else zincirleri yerine her aşamayı ayrı bir sınıfa koyup siparişin o anki aşama nesnesine iş devretmesini öneren kalıp hangisidir?', 'State (durum)', ['Memento (hatıra)', 'Iterator (yineleyici)', 'Prototype (ön örnek)'], 'State kalıbında nesnenin davranışı içteki durum nesnesine yetkilendirilir; durum değişince nesne sanki sınıfını değiştirmiş gibi farklı davranır.'),
  ('Bir oyunda karakterin o anki durumu kapsüllemeyi bozmadan bir nesneye kaydediliyor ve gerektiğinde bu kayıttan geri yükleniyor. Bu \'kayıt noktası\' davranışını sağlayan kalıp hangisidir?', 'Memento (hatıra)', ['Command (komut)', 'Proxy (vekil)', 'Flyweight (sinek siklet)'], 'Memento, nesnenin iç durumunun anlık görüntüsünü yalnız sahibinin okuyabileceği bir nesnede saklar; böylece geri yükleme yapılırken iç ayrıntılar dışarıya açılmaz.'),
  ('Bir havalimanında uçaklar birbirleriyle doğrudan konuşmak yerine bütün iletişimi kontrol kulesi üzerinden yürütüyor. Nesneler arasındaki çoka çok bağlantıları tek bir merkez nesneye toplayan bu kalıp hangisidir?', 'Mediator (arabulucu)', ['Observer (gözlemci)', 'Composite (bileşik)', 'Iterator (yineleyici)'], 'Arabulucu, birbirine doğrudan başvuran çok sayıda nesnenin bağlaşımını azaltır; nesneler yalnız arabulucuyu tanır.'),
  ('Bir yardım masası sisteminde talep önce birinci kademe destek nesnesine gidiyor; o çözemezse ikinci kademeye, o da çözemezse uzmana aktarılıyor. Bu yapı hangi kalıptır?', 'Chain of Responsibility (sorumluluk zinciri)', ['Command (komut nesnesi) kalıbı', 'Mediator (arabulucu)', 'Template Method (şablon yöntem)'], 'Sorumluluk zincirinde istek, işleyicilerden biri onu karşılayana kadar zincir boyunca iletilir; gönderen, isteği kimin işleyeceğini bilmez.'),
  ('Bir müşterinin indirim nesnesi bazen hiç yoksa kodun her yerinde \'if (indirim != null)\' denetimi yapmak yerine, hiçbir şey yapmayan ama aynı arayüzü uygulayan IndirimYok nesnesi kullanmayı öneren kalıp hangisidir?', 'Null Object (boş nesne)', ['Singleton (tekil)', 'Proxy (vekil)', 'Prototype (ön örnek)'], 'Boş nesne, \'yokluk\' durumunu nötr davranışlı gerçek bir nesneyle temsil eder; böylece null denetimleri azalır ve NullPointerException riski düşer.'),
  ('Java\'da Arrays.sort(dizi, comparator) çağrısında karşılaştırma mantığının ayrı bir Comparator nesnesiyle verilmesi hangi kalıba en çok benzer?', 'Strategy', ['Singleton', 'Memento', 'Flyweight'], 'Sıralama algoritması sabittir; değişen karşılaştırma ölçütü ayrı bir nesne olarak dışarıdan verilir. Bu, strateji kalıbının bir uygulamasıdır.'),
  ('Bir arayüz düğmesine tıklandığında çalışacak eylemin düğmeye bir nesne olarak verilmesi; aynı eylem nesnesinin menüde ve klavye kısayolunda da kullanılabilmesi hangi kalıbın kazancıdır?', 'Command', ['Facade', 'Bridge', 'Iterator'], 'İsteği çağırandan (düğme, menü) ayıran komut nesnesi, aynı işlemin birden çok tetikleyiciye bağlanmasını kolaylaştırır.'),
  ('Python\'da bir sınıfa __iter__ yöntemi eklenip bu yöntemin yield ile öğe üreten bir üreteç olarak yazılması, hangi kalıbın dile gömülü bir uygulamasıdır?', 'Iterator', ['Observer', 'Command', 'Builder'], 'yield içeren __iter__ her çağrıldığında yeni bir yineleyici döndürür; for döngüsü bu yineleyiciden next ile öğeleri alır.'),
  ('Bağımlılıkların yapıcı parametresiyle verilmesinin, servisin içinde new ile oluşturulmasına göre birim testi açısından yararı nedir?', 'Testte gerçek veritabanı yerine sahte bir nesne verilebilir', ['Testler derleme zamanında kendiliğinden yazılır', 'Sınıfın hiç yapıcıya ihtiyacı kalmaz', 'Servis program boyunca yalnız tek bir kez örneklenebilir, ikincisi engellenir'], 'Bağımlılık dışarıdan geldiği için test, aynı arayüzü uygulayan sahte (mock) bir nesne vererek sınıfı dış sistemlerden yalıtılmış biçimde sınayabilir.'),
  ('Bağımlılık enjeksiyonunun üç yaygın biçimi olarak hangileri sayılır?', 'Yapıcı, setter ve arayüz enjeksiyonu', ['Derleme, bağlama ve yükleme enjeksiyonu', 'Statik, dinamik ve sanal enjeksiyon', 'Sınıf, paket ve modül enjeksiyonu'], 'Bağımlılık yapıcı parametresiyle, bir setter yöntemiyle ya da bağımlılığı alan bir arayüz yöntemiyle verilebilir; zorunlu bağımlılıklar için yapıcı enjeksiyonu genellikle tercih edilir.'),
  ('Çatıların (framework) programcının kodunu çağırması, yani akışın denetiminin uygulama kodundan çatıya geçmesi hangi ilkeyle anlatılır?', 'Denetimin tersine çevrilmesi (Inversion of Control)', ['Bilginin gizlenmesi (information hiding)', 'Kendini tekrar etmeme (DRY)', 'İlgilerin birbirinden ayrılması (separation of concerns)'], 'IoC\'de programcı yalnız belirli noktalara takılan parçaları yazar; ne zaman çağrılacaklarına çatı karar verir. Bağımlılık enjeksiyonu bu ilkenin bir uygulamasıdır.'),
  ('Denetimin tersine çevrilmesi ilkesi çoğu zaman hangi esprili sözle özetlenir?', '\'Bizi aramayın, biz sizi ararız\'', ['\'Ördek gibi vaklıyorsa ördektir\'', '\'Önce çalıştır, sonra hızlandır\'', '\'Az olan çoktur\''], 'Hollywood ilkesi olarak da anılan bu söz, bileşenlerin çatıyı çağırmak yerine çatı tarafından çağrılmayı beklemesini anlatır.'),
  ('Üst sınıfta yapılan, kendi içinde doğru görünen bir değişikliğin, haberdar olunmayan alt sınıfları bozması sorununa ne ad verilir?', 'Kırılgan taban sınıf problemi', ['Elmas problemi', 'Yoyo problemi', 'Daire-elips (kare-dikdörtgen) problemi'], 'Alt sınıflar üst sınıfın iç davranışına bağımlı olabildiği için kalıtım güçlü bir bağlaşım yaratır; üst sınıftaki masum bir değişiklik bile alt sınıfları bozabilir.'),
  ('Bir programcının bir yöntemin gerçekte ne yaptığını anlamak için çok derin bir kalıtım hiyerarşisinde sürekli yukarı aşağı gidip gelmek zorunda kalmasına ne ad verilir?', 'Yoyo problemi', ['Elmas problemi', 'Kırılgan taban sınıf problemi', 'Tanrı nesnesi'], 'Hiyerarşi derinleştikçe davranış birçok sınıfa dağılır ve geçersiz kılmalar yüzünden hangi sürümün çalıştığını izlemek zorlaşır.'),
  ('Telefon numarası, para tutarı ve e-posta adresi gibi kavramların ayrı sınıflar yerine her yerde düz String ve double olarak taşınması hangi kod kokusudur?', 'İlkel türe saplantı (primitive obsession)', ['Özellik kıskançlığı (feature envy)', 'Tanrı nesnesi karşı kalıbı (God object)', 'Reddedilen miras (refused bequest)'], 'Kendi sınıfı olmayan kavramların doğrulama ve davranışları kod boyunca dağılır; Para ya da Eposta gibi küçük değer nesneleri bu kokuyu giderir.'),
  ('C#\'ta struct Nokta { public int X; } tanımlı. Nokta a = new Nokta(); a.X = 1; Nokta b = a; b.X = 5; satırlarından sonra a.X kaçtır?', '1', ['5', '0', '6'], 'C#\'ta struct bir değer türüdür; atama tüm alanları kopyalar. b ayrı bir kopya olduğundan b.X\'in değişmesi a\'yı etkilemez.'),
  ('Swift\'te struct ile class arasındaki temel fark hangisidir?', 'struct atamada kopyalanır; class nesnesi paylaşılır', ['class değer türüdür; struct başvuru türüdür ve paylaşılır', 'struct yöntem içeremez; class içerebilir', 'İkisi de başvuru türüdür; yalnız adları farklıdır'], 'Swift\'te struct\'lar atamada ve işleve aktarımda kopyalanır; class nesneleri ise başvuruyla paylaşılır. Ayrıca kalıtım yalnız class\'larda vardır.'),
  ('Java 16 ile gelen record Nokta(int x, int y) {} bildirimi için hangisi doğrudur?', 'equals, hashCode, toString ve x(), y() erişimcileri otomatik üretilir', ['Her alan için setter yöntemleri de derleyicice otomatik olarak üretilir', 'Başka bir sınıftan extends ile türetilebilir', 'Alanları her zaman public ve değiştirilebilirdir'], 'Record\'lar değişmez veri taşıyıcılarıdır; alanlar private final olur, bileşenlere göre equals/hashCode/toString ve erişimciler derleyicice üretilir. Record\'lar örtük olarak final\'dır ve başka sınıfı genişletemez.'),
  ('Kotlin\'de data class Kisi(val ad: String, val yas: Int) için val k2 = k1.copy(yas = 30) satırı ne yapar?', 'Adı k1 ile aynı, yaşı 30 olan yeni bir nesne oluşturur', ['k1 nesnesinin yaşını 30 yapar ve k2\'ye atar', 'k1\'in derin kopyasını alır, yaşı değiştirmez', 'Derleme hatası verir, çünkü yas val\'dir'], 'data class için üretilen copy() yöntemi, belirtilen alanları değiştirilmiş yeni bir örnek döndürür; özgün nesne değişmez.'),
  ('Kotlin\'de var ad: String? = null tanımlıyken ad?.length ifadesi ne döndürür?', 'null', ['0', 'NullPointerException', 'Derleme hatası'], '?. güvenli çağrı işleci, alıcı null ise çağrıyı yapmaz ve null döndürür; böylece null denetimi kısa yoldan yapılır.'),
  ('Java 8 ile gelen Optional<T> türünün tasarım amacı nedir?', 'Bir değerin bulunmayabileceğini dönüş türünde açıkça göstermek', ['Sınıflardaki bütün başvuru türündeki alanların yerini kalıcı olarak almak', 'Nesnelerin otomatik olarak kopyalanmasını sağlamak', 'Çöp toplayıcıyı devre dışı bırakmak'], 'Optional, \'sonuç olmayabilir\' durumunu türün bir parçası yapar; çağıran isPresent, orElse gibi yöntemlerle bu durumu açıkça ele almaya yönlendirilir.'),
  ('Alan güdümlü tasarımda (DDD) Para(100, "TRY") gibi kimliği olmayan, yalnız değerleriyle karşılaştırılan ve genellikle değişmez tasarlanan nesnelere ne ad verilir?', 'Değer nesnesi (value object)', ['Varlık (entity)', 'Veri aktarım nesnesi (data transfer object)', 'Servis nesnesi'], 'Değer nesnelerinde iki nesne alanları aynıysa eşit sayılır; kimlikleri önemsizdir. Varlıklar ise değerleri değişse de kimlikleriyle izlenir.'),
  ('Alan güdümlü tasarımda bir Müşteri nesnesinin adı ve adresi değişse bile müşteri numarasıyla aynı müşteri olarak izlenmesi, bu nesnenin hangi türde olduğunu gösterir?', 'Varlık (entity)', ['Değer nesnesi (value object)', 'Fabrika (factory)', 'Depo (repository)'], 'Varlıklar zaman içinde değişen bir yaşam döngüsüne ve kalıcı bir kimliğe sahiptir; eşitlikleri bu kimliğe göre belirlenir.'),
  ('C++\'ta Nokta* p = &n; tanımlıyken p->x ifadesi neye eşdeğerdir?', '(*p).x', ['*p.x', '&p.x', 'p.x'], '-> işleci, işaretçinin gösterdiği nesnenin üyesine erişir; önce işaretçiyi çözüp sonra nokta işleciyle üyeye ulaşmanın kısa yazımıdır.'),
  ('Java\'da enum Renk { KIRMIZI, YESIL } değerlerini karşılaştırırken equals yerine == kullanmak neden güvenlidir?', 'Her enum sabitinin JVM\'de tek bir örneği vardır', ['== enumlarda otomatik olarak equals\'ı çağırır', 'Enum değerleri ilkel int olarak saklanır', 'Derleyici enum karşılaştırmalarını derleme zamanında yapar'], 'Enum sabitleri sınıf yüklenirken bir kez oluşturulur ve yeni örnek üretilemez; bu yüzden kimlik karşılaştırması değer karşılaştırmasıyla aynı sonucu verir.'),
  ('Python\'da a = Kisi("Ali"); b = a; b.ad = "Veli"; del b çalıştırıldıktan sonra a.ad nedir?', 'Veli', ['Ali', 'None', 'NameError'], 'b = a yeni nesne oluşturmaz; iki ad aynı nesneye bağlanır. b üzerinden yapılan değişiklik nesnenin kendisini değiştirir; del b ise yalnız b adını siler, nesne a üzerinden yaşamaya devam eder.'),
  ('Python\'da A sınıfında def f(self): return self.g() ve def g(self): return "A" var; B(A) sınıfı yalnız g\'yi def g(self): return "B" olarak yeniden tanımlıyor. B().f() ne döndürür?', '\'B\'', ['\'A\'', '\'AB\'', 'AttributeError'], 'f, A\'da tanımlı olsa da self bir B nesnesidir. self.g() çağrısı nesnenin gerçek sınıfından başlayarak arandığı için B\'deki g çalışır.'),
  ('Java\'da A sınıfında static int sayac = 0; ve A() { sayac++; } var; B extends A sınıfında B() { sayac++; } tanımlı. new B(); new A(); çalıştırıldıktan sonra A.sayac kaçtır?', '3', ['2', '1', '4'], 'new B() önce A\'nın yapıcısını, sonra B\'ninkini çalıştırır ve ortak statik sayaç iki kez artar. new A() bir kez daha artırır: toplam 3.'),
  ('Python\'da bir sınıfta __str__ tanımlanmamış, yalnız __repr__ tanımlanmışsa print(nesne) ne yapar?', '__repr__ çıktısını kullanır', ['Sınıf adını ve adresini yazar', 'TypeError fırlatır', 'Boş satır yazar'], 'object\'ten gelen varsayılan __str__, __repr__ yöntemini çağırır; bu yüzden yalnız __repr__ tanımlamak iki durumu da kapsar.'),
  ('Python\'da Daire sınıfının __init__ yöntemi self.r = r ve self.alan = 3.14 * r * r atamalarını yapıyor. d = Daire(1); d.r = 2 sonrasında d.alan hangi değeri verir ve neden?', '3.14; alan yalnız oluşturulurken hesaplanmıştır', ['12.56; alan r ile otomatik güncellenir', '6.28; alan yarıçapla doğru orantılı güncellenir', 'AttributeError; alan silinmiştir'], 'alan sıradan bir niteliktir ve r değişince yeniden hesaplanmaz. alan bir @property olarak tanımlansaydı her okumada güncel r ile hesaplanırdı.'),
  ('Python\'da k = Kisi("Ece") ve sınıfta def selam(self): return "Ben " + self.ad tanımlı. f = k.selam; f() çağrısı ne döndürür?', '\'Ben Ece\'', ['TypeError; self eksiktir', '\'Ben \'', 'AttributeError; ad bulunamaz'], 'k.selam bir bağlı yöntem (bound method) döndürür; nesne bu yönteme önceden bağlandığı için f() çağrısında self otomatik olarak k olur.'),
  ('Java\'da Hayvan[] dizi = { new Kedi(), new Kopek(), new Kedi() }; tanımlı ve her sınıf ses() yöntemini kendine göre geçersiz kılıyor. for (Hayvan h : dizi) h.ses(); döngüsü kaç farklı ses() gövdesini çalıştırır?', '2', ['1', '3', '0'], 'Dizide üç nesne olsa da yalnız iki farklı gerçek sınıf vardır. Her çağrı nesnenin sınıfına göre bağlandığından Kedi\'nin gövdesi iki kez, Kopek\'inki bir kez çalışır.'),
  ('Python\'da class Ogrenci: okul = "Fen Lisesi" tanımlı. o = Ogrenci(); o.okul = "Anadolu Lisesi"; Ogrenci.okul = "Meslek Lisesi" çalıştırıldıktan sonra o.okul ne verir?', '\'Anadolu Lisesi\'', ['\'Meslek Lisesi\'', '\'Fen Lisesi\'', 'AttributeError'], 'o.okul ataması nesneye ait bir örnek niteliği oluşturur ve sınıf niteliğini gölgeler. Sınıf niteliğinin sonradan değişmesi bu nesneyi etkilemez.'),
  ('Java\'da Sekil soyut sınıfının yapıcısı "S", Kare sınıfının yapıcısı "K" yazdırıyor. Sekil s = new Kare(); Sekil t = new Kare(); satırları çalışınca çıktı nedir?', 'SKSK', ['SK', 'KSKS', 'SSKK'], 'Soyut sınıftan doğrudan nesne oluşmasa da alt sınıf nesnesi oluşurken onun yapıcısı çalışır. Her new Kare() önce S sonra K yazdırır.'),
  ('Python\'da bir sınıfın üzerine @dataclass süslemesi konup yalnız ad: str ve yas: int alanları bildirildiğinde, programcı yazmasa da hangi yöntemler otomatik oluşturulur?', '__init__, __repr__ ve __eq__', ['__init__, __del__ ve __hash__ ile birlikte __lt__', 'Yalnız __init__ ve hiçbir karşılaştırma yöntemi', '__str__, __len__ ve __iter__ yöntemleri'], 'dataclass varsayılan olarak alanlara göre __init__, okunaklı bir __repr__ ve alanları karşılaştıran __eq__ üretir; sıralama yöntemleri için order=True gerekir.'),
  ('Python dataclass\'larında __post_init__ yöntemi ne zaman ve hangi amaçla kullanılır?', '__init__ bittikten sonra doğrulama ya da türetilmiş alan hesabı için', ['Nesne silinmeden hemen önce kaynakları bırakmak için', 'Sınıf tanımlanırken bir kez, statik alanları kurmak için', 'Nesne kopyalanırken bütün alanları ve iç nesneleri derinlemesine çoğaltmak için'], 'dataclass\'ın ürettiği __init__ alanları atadıktan sonra __post_init__\'i çağırır; böylece programcı kendi __init__\'ini yazmadan ek işlemler yapabilir.'),
  ('Python\'da @dataclass(order=True) seçeneği sınıfa hangi yeteneği kazandırır?', 'Nesnelerin alanlar sırasıyla <, <=, >, >= ile karşılaştırılabilmesi', ['Alanların tanım sırası yerine alfabetik sıraya göre yeniden dizilmesi', 'Nesnelerin oluşturulma sırasının kaydedilmesi', 'Alanların değiştirilemez hale getirilmesi'], 'order=True, alanları tanım sırasıyla bir demet gibi karşılaştıran sıralama yöntemlerini üretir; böylece nesneler doğrudan sorted ile sıralanabilir.'),
  ('Python\'da from enum import Enum; class Renk(Enum): KIRMIZI = 1; YESIL = 2 tanımlı. Renk(2).name ifadesi ne verir?', '\'YESIL\'', ['2', '\'Renk.YESIL\'', '\'KIRMIZI\''], 'Renk(2) değeri 2 olan üyeyi, yani Renk.YESIL\'i döndürür; name özelliği üyenin adını metin olarak verir.'),
  ('Python\'da Nokta = namedtuple("Nokta", ["x", "y"]); p = Nokta(1, 2) sonrasında p.x = 5 yazılırsa ne olur?', 'AttributeError fırlatılır', ['p.x 5 olur', 'p yerine yeni bir Nokta oluşur', 'p.x 5, p[0] 1 olarak kalır'], 'namedtuple bir demet alt sınıfı oluşturur; alanlara adla erişilebilir ama demetler değiştirilemez olduğundan atama reddedilir. Yeni değer için p._replace(x=5) kullanılır.'),
  ('Python\'da bir nesnenin ait olduğu sınıfın adını metin olarak elde etmek için hangisi kullanılır?', 'nesne.__class__.__name__', ['nesne.__name__', 'nesne.__dict__[\'class\']', 'nesne.__module__'], '__class__ nesnenin sınıfını verir; sınıfların __name__ niteliği ise sınıf adını taşır. Sıradan nesnelerin kendi __name__ niteliği yoktur.'),
  ('Python\'da @staticmethod olarak tanımlanmış donustur() yöntemi k = Olcu() nesnesi üzerinden k.donustur(5) biçiminde çağrılırsa ne olur?', 'Sorunsuz çalışır; nesne argüman olarak geçirilmez', ['TypeError; statik yöntem yalnız sınıf adıyla çağrılır', 'Nesne ilk argüman olarak gizlice geçirilir', 'Yöntem örnek yöntemine dönüşür'], 'Statik yöntemler hem sınıf hem nesne üzerinden çağrılabilir; her iki durumda da örtük self ya da cls parametresi almazlar.'),
  ('Kotlin\'de static anahtar sözcüğü bulunmaz. Bir sınıfa, nesne oluşturmadan SinifAdi.yontem() biçiminde çağrılabilen üyeler eklemek için sınıf içinde ne tanımlanır?', 'companion object bloğu', ['init bloğu ve içinde fun bildirimi', 'open class bildirimi', 'sealed interface bildirimi'], 'companion object içindeki üyeler sınıf adı üzerinden çağrılır ve Java\'daki statik üyelerin karşılığı olarak kullanılır.'),
  ('Kotlin\'de object Ayarlar { var dil = "tr" } biçimindeki bildirim ne oluşturur?', 'Dil düzeyinde tek örnekli bir nesne', ['Her kullanımda yeni örnek üreten bir sınıf', 'Yalnız arayüz işlevi gören soyut bir tür', 'Derleme zamanında silinen bir tür takma adı'], 'object bildirimi sınıf tanımını ve tek örneğini birlikte oluşturur; ilk erişimde tembelce ve iş parçacığı açısından güvenli biçimde başlatılır.'),
  ('C#\'ta partial anahtar sözcüğüyle bildirilen bir sınıf için hangisi doğrudur?', 'Tanımı birden çok dosyaya bölünebilir, derlemede birleştirilir', ['Sınıfın yalnız ilk dosyadaki kısmı derlenir, kalan kısımlar yok sayılır', 'Sınıftan yalnız tek bir nesne oluşturulabilir', 'Sınıfın alanları başka sınıflarla paylaşılır'], 'partial sınıflar, örneğin araçların ürettiği kodla programcının yazdığı kodun ayrı dosyalarda tutulmasına olanak verir; derleyici bütün parçaları tek sınıf olarak birleştirir.'),
  ('Swift dilinde Java\'daki arayüzlerin (interface) karşılığı olan ve sınıfların, struct\'ların ve enum\'ların uyabildiği yapı hangisidir?', 'protocol', ['trait', 'mixin', 'extension'], 'Swift\'te protocol, bir türün sağlaması gereken yöntem ve özellikleri tanımlar; class\'lar kadar değer türleri de protokollere uyabilir.'),
  ('Java\'daki enum türleriyle ilgili hangisi doğrudur?', 'Alan, yapıcı ve yöntem içerebilirler', ['Yalnız sabit adlar içerebilirler', 'Her sabit için ayrı new çağrısı gerekir', 'Başka bir sınıftan extends ile türetilebilirler'], 'Java enum\'ları tam sınıflardır; örneğin Gezegen enum\'u her sabit için kütle ve yarıçap alanları taşıyıp yerCekimi() yöntemi sunabilir.'),
  ('Aşağıdaki yöntemlerden hangisi Java\'da her nesnenin java.lang.Object\'ten devraldığı yöntemler arasında yer almaz?', 'compareTo', ['equals', 'hashCode', 'getClass'], 'compareTo Comparable arayüzüne aittir ve yalnız bu arayüzü uygulayan sınıflarda bulunur. equals, hashCode, toString ve getClass ise Object\'te tanımlıdır.'),
  ('C#\'ta alt sınıftan üst sınıfın yapıcısını ya da geçersiz kılınmış bir yöntemini çağırmak için Java\'daki super\'in karşılığı olan anahtar sözcük hangisidir?', 'base', ['parent', 'super', 'self'], 'C#\'ta base.Yontem() ile üst sınıf sürümü çağrılır; yapıcı zincirinde ise public Kedi(string ad) : base(ad) yazılır.'),
  ('C++\'ta bir üye işlevin içinde this ifadesinin türü için hangisi doğrudur?', 'Nesneyi gösteren bir işaretçidir; üyeye this->x ile erişilir', ['Nesnenin bir kopyasıdır; üyeye this.x ile erişilir', 'Sınıfın kendisini gösteren statik bir başvurudur', 'Yalnız yapıcılarda kullanılabilen bir anahtar sözcüktür'], 'C++\'ta this, işlevin çağrıldığı nesnenin adresini taşıyan bir işaretçidir; bu yüzden üyelere ok işleciyle erişilir.'),
  ('Kotlin\'de sınıf başlığındaki class Kisi(val ad: String, var yas: Int) biçimindeki yazıma ne ad verilir ve ne sağlar?', 'Birincil yapıcı; parametreleri doğrudan özellik olarak bildirir', ['İkincil yapıcı; yalnız parametreleri doğrular', 'Veri sınıfı; equals, hashCode ve toString yöntemlerini otomatik üretir', 'Statik fabrika; tek örnek döndürür'], 'Birincil yapıcıda val ya da var ile yazılan parametreler aynı zamanda sınıfın özellikleri olur; val salt okunur, var değiştirilebilir özellik oluşturur.'),
  ('Java\'da denetlenen (checked) istisnalarla denetlenmeyen (unchecked) istisnalar arasındaki fark hangisidir?', 'Denetlenenler yakalanmalı ya da throws ile bildirilmeli; ötekiler için zorunlu değil', ['Denetlenmeyenler derleme hatası sayılır; denetlenenler ise yalnız çalışma anında oluşur', 'Denetlenenler yalnız Error sınıfından türer', 'İkisi arasında derleyici açısından hiçbir fark yoktur'], 'IOException gibi denetlenen istisnaları derleyici izler. RuntimeException ve alt sınıfları (ör. NullPointerException) ise denetlenmez; yakalanmaları ya da bildirilmeleri zorunlu değildir.'),
  ('Java\'da OutOfMemoryError ve StackOverflowError gibi sınıfların türediği, uygulamaların genellikle yakalamaya çalışmaması gereken ciddi sorunları temsil eden sınıf hangisidir?', 'Error', ['RuntimeException', 'IOException', 'Exception'], 'Throwable\'ın iki ana kolu Exception ve Error\'dır. Error, programın genellikle toparlanamayacağı sistem düzeyindeki sorunları anlatır.'),
  ('Python\'da kendi istisna sınıfını tanımlarken en yaygın olarak hangi sınıftan türetilmesi önerilir?', 'Exception', ['BaseException', 'object', 'Error'], 'Kullanıcı tanımlı istisnalar Exception\'dan türetilmelidir; böylece except Exception blokları onları yakalar, ama programı sonlandırma istisnaları ayrı kalır.'),
  ('Craig Larman\'ın GRASP ilkelerinden \'Bilgi Uzmanı\' (Information Expert) ilkesine göre, bir siparişin toplam tutarını hesaplama sorumluluğu hangi sınıfa verilmelidir?', 'Sipariş kalemlerini ve fiyatlarını tutan Siparis sınıfına', ['Kullanıcı arayüzündeki SiparisEkrani sınıfına', 'Programdaki bütün hesapları üstlenen genel bir Yardimci sınıfına', 'Veritabanı bağlantısını yöneten Baglanti sınıfına'], 'Bilgi uzmanı ilkesi, bir sorumluluğu onu yerine getirmek için gereken bilgiye sahip sınıfa vermeyi önerir; toplamı hesaplamak için gereken kalemler Siparis\'tedir.'),
  ('GRASP\'ın \'Yaratıcı\' (Creator) ilkesine göre bir SiparisKalemi nesnesini oluşturma sorumluluğu öncelikle hangi sınıfa verilmelidir?', 'Kalemleri içeren ve kaydeden Siparis sınıfına', ['Ödemeyi işleyen Odeme sınıfına', 'Ürün kataloğunu kullanıcıya gösteren Ekran sınıfına', 'Programın main yöntemini içeren sınıfa'], 'Yaratıcı ilkesine göre B nesnelerini, onları içeren, kaydeden ya da onları başlatmak için gereken verilere sahip A sınıfı oluşturmalıdır.'),
  ('GRASP\'ta kullanıcı arayüzünden gelen sistem olaylarını (ör. \'satışı tamamla\') karşılayıp alan nesnelerine yönlendiren, arayüz dışındaki ilk nesneye hangi rol verilir?', 'Denetleyici (controller)', ['Saf uydurma (pure fabrication)', 'Bilgi uzmanı (information expert)', 'Korunan değişim (protected variations)'], 'Denetleyici rolü, arayüz katmanını iş mantığından ayırır; arayüz nesneleri işi doğrudan yapmaz, olayları denetleyiciye iletir.'),
  ('Nesne yönelimli tasarımda her sınıfın adının, sorumluluklarının ve birlikte çalıştığı sınıfların küçük kâğıt kartlara yazıldığı beyin fırtınası tekniğine ne ad verilir?', 'CRC kartları', ['Kanban kartları', 'UML kartları', 'Persona kartları'], 'Sınıf-Sorumluluk-İşbirlikçi (Class-Responsibility-Collaborator) kartları, Ward Cunningham ve Kent Beck\'in tanıttığı, ekipçe sınıf tasarımı yapmaya yarayan bir tekniktir.'),
  ('Soyutlama ile kapsülleme arasındaki fark en iyi hangisiyle açıklanır?', 'Soyutlama neyin gösterileceğini seçer; kapsülleme ayrıntıları gizler', ['Soyutlama erişimi kapatır; kapsülleme yalnız sınıf adlarını seçer', 'İkisi aynı kavramın farklı adlarıdır', 'Soyutlama yalnız kalıtımla, kapsülleme yalnız arayüzle yapılır'], 'Soyutlama bir nesnenin problem için önemli özelliklerini öne çıkarıp gereksizleri dışarıda bırakır; kapsülleme ise bu özelliklerin nasıl gerçekleştirildiğini gizleyip erişimi denetler.'),
  ('Bir RaporOlusturucu sınıfı, yalnız olustur(Yazici y) yönteminin parametresi olarak bir Yazici kullanıyor ve onu alan olarak saklamıyor. UML\'de bu iki sınıf arasındaki en zayıf ilişki hangisidir?', 'Bağımlılık (dependency)', ['Bileşim (composition)', 'Toplama (aggregation)', 'Genelleme (generalization)'], 'Bir sınıf diğerini yalnız geçici olarak, parametre ya da yerel değişken olarak kullanıyorsa aralarında bağımlılık (\'kullanır\') ilişkisi vardır; UML\'de kesikli okla gösterilir.'),
  ('Chidamber-Kemerer ölçütlerinden CBO (Coupling Between Objects) değerinin düşük olması genellikle neden istenir?', 'Az sınıfa bağlı sınıf değişikliklerden daha az etkilenir', ['Sınıfın daha çok kalıtım alabilmesini sağladığı için', 'Sınıfın daha çok yöntem içermesine izin verdiği için', 'Derleyicinin daha hızlı çalışmasını sağladığı için'], 'CBO bir sınıfın bağlaştığı başka sınıfların sayısıdır; düşük bağlaşım sınıfın yeniden kullanılmasını, sınanmasını ve bakımını kolaylaştırır.'),
  ('UML sınıf diyagramında bir sınıf adının ya da yöntem adının italik yazılması neyi belirtir?', 'Soyut olduğunu', ['Statik olduğunu', 'Özel (private) olduğunu', 'Değişmez olduğunu'], 'UML\'de soyut sınıflar ve soyut işlemler italik yazılır ya da yanlarına {abstract} etiketi konur.'),
  ('UML sınıf diyagramında bir niteliğin ya da işlemin altının çizilmesi neyi gösterir?', 'Sınıf düzeyinde (static) olduğunu', ['Soyut olduğunu', 'Türetilmiş (hesaplanan) bir nitelik olduğunu', 'Yalnız okunur olduğunu'], 'Altı çizili üyeler nesnelere değil sınıfın kendisine aittir; Java ve C++\'taki static üyelerin karşılığıdır.'),
  ('UML sınıf diyagramında Musteri ile Siparis arasındaki ilişkinin Siparis ucunda 0..* yazması ne anlama gelir?', 'Bir müşterinin hiç ya da istendiği kadar siparişi olabilir', ['Bir müşterinin tam olarak bir siparişi olur', 'Bir siparişin hiç müşterisi olmayabilir ya da birden çok müşterisi olabilir', 'Bir müşterinin en çok sıfır siparişi olabilir'], 'Çokluk (multiplicity) gösteriminde 0..* alt sınırın 0, üst sınırın sınırsız olduğunu belirtir; 1..* ise en az bir anlamına gelir.'),
  ('Her yöntemin this döndürmesi sayesinde sorgu.secim("ad").kosul("yas > 18").sirala("ad") biçiminde art arda çağrı yazılabilen arayüz tasarımına ne ad verilir?', 'Akıcı arayüz (fluent interface)', ['İşaretleyici arayüz (marker interface)', 'İşlevsel arayüz (functional interface)', 'Gösterge arayüzü (dashboard)'], 'Akıcı arayüzlerde yöntemler nesnenin kendisini döndürerek zincirlenir; Builder kalıbı ve sorgu oluşturucular bu biçimi sık kullanır.'),
  ('Java\'da Serializable bir sınıfın sifre alanı transient olarak işaretlenmiştir. Nesne serileştirilip geri okunduğunda bu alan için ne olur?', 'Kaydedilmez; geri okunduğunda varsayılan değerle (null) gelir', ['Şifrelenerek kaydedilir ve aynen geri gelir', 'Serileştirme bu alan yüzünden NotSerializableException istisnası fırlatır', 'Alan static olur ve bütün nesnelerce paylaşılır'], 'transient, alanın nesnenin kalıcı durumuna dahil edilmeyeceğini belirtir; şifre gibi hassas ya da yeniden hesaplanabilen veriler için kullanılır.'),
  ('C++\'ta std::unique_ptr<Dosya> akıllı işaretçisi için hangisi doğrudur?', 'Tek sahiptir; kopyalanamaz, yalnız taşınabilir', ['Sahiplerini sayar, son sahip gidince nesneyi siler', 'Nesneyi asla silmez, yalnız gözlemler', 'Birden çok kopyası aynı anda nesneyi silebilir'], 'unique_ptr özel sahiplik anlatır; kapsamdan çıkınca nesneyi siler. Sahipliği devretmek için std::move kullanılır.'),
  ('C++\'ta std::shared_ptr ile yönetilen bir nesne ne zaman silinir?', 'Onu gösteren son shared_ptr yok edildiğinde', ['İlk shared_ptr kapsamdan çıktığında', 'Program sona erdiğinde', 'Elle delete çağrıldığında'], 'shared_ptr bir başvuru sayacı tutar; her kopya sayacı artırır, her yok oluş azaltır. Sayaç sıfıra inince nesne silinir.'),
  ('C++\'ta Taban* p bir Kedi nesnesini gösteriyor. Kopek* k = dynamic_cast<Kopek*>(p); satırından sonra k\'nin değeri ne olur?', 'nullptr', ['Kedi nesnesinin adresi', 'Yeni oluşturulmuş bir Kopek nesnesi', 'Tanımsız bir adres'], 'dynamic_cast çalışma anında tür denetimi yapar; işaretçi dönüşümü başarısızsa nullptr döndürür. Başvuru dönüşümünde ise std::bad_cast fırlatılır.'),
  ('C++\'ta Nokta a; Nokta b = a; Nokta c(a); satırları çalışınca Nokta\'nın kopya yapıcısı kaç kez çağrılır?', '2', ['1', '3', '0'], 'Nokta b = a; atama gibi görünse de yeni nesne oluşturduğu için kopya yapıcıyı çağırır; Nokta c(a); de öyle. a ise varsayılan yapıcıyla oluşur.'),
  ('C++\'ta Nokta a, b; tanımlandıktan sonra b = a; satırı çalışınca hangi özel üye çağrılır?', 'Kopya atama işleci', ['Kopya yapıcı', 'Varsayılan yapıcı', 'Taşıma yapıcısı'], 'b zaten var olduğu için yeni nesne oluşturulmaz; var olan nesneye değer aktaran operator= çağrılır.'),
  ('C++\'ta Kilit(const Kilit&) = delete; bildirimi sınıfa eklenirse ne olur?', 'Kilit nesneleri kopyalanamaz; kopyalama girişimi derlenmez', ['Kilit nesneleri yalnız silinebilir, oluşturulamaz', 'Kopya yapıcı silinir ama derleyicice otomatik olarak yeniden üretilir', 'Kilit nesneleri kopyalanınca özgün nesne silinir'], '= delete ile bir işlev açıkça yasaklanır. Mutex gibi kopyalanması anlamsız kaynakları temsil eden sınıflarda kopya yapıcı ve kopya ataması bu yolla kapatılır.'),
  ('C++\'ta Sekil saf sanal işlev içeren soyut bir sınıftır. Sekil s; ile Sekil* p = new Daire(); satırları için hangisi doğrudur?', 'İlki derlenmez, ikincisi geçerlidir', ['İkisi de geçerlidir', 'İkisi de derlenmez', 'İlki geçerlidir, ikincisi derlenmez'], 'Soyut sınıftan nesne oluşturulamaz; ancak soyut türde işaretçi ya da başvuru tanımlanıp somut alt sınıf nesnelerini göstermesi çok biçimliliğin temelidir.'),
  ('C++\'ta yapıcısı ve yıkıcısı ekrana yazı yazan Nokta sınıfı için void f() { Nokta* p = new Nokta(); } işlevi çağrılırsa yıkıcı ne zaman çalışır?', 'Hiç çalışmaz; delete yapılmadığı için bellek sızar', ['f bittiğinde kendiliğinden çalışır', 'Program sonunda C++ çöp toplayıcısı onu bulup çalıştırır', 'p\'ye nullptr atandığında çalışır'], 'new ile öbekte oluşturulan nesne yalnız delete ile silinir. İşaretçi kapsamdan çıkınca nesne erişilemez hale gelir ama silinmez; akıllı işaretçiler bu sorunu önler.'),
  ('C++\'ta public kalıtımla türetilen bir sınıfta taban sınıfın protected üyeleri hangi erişim düzeyinde kalır?', 'Korumalı olarak kalırlar', ['Herkese açık hale gelirler', 'Özel hale gelirler', 'Alt sınıfa hiç devredilmezler'], 'Public kalıtımda tabanın public üyeleri public, protected üyeleri protected kalır; private üyeler ise türemiş sınıftan doğrudan erişilemez.'),
  ('Java\'da Kedi k = null; ifadesinden sonra k instanceof Kedi ifadesi ne verir?', 'false', ['true', 'NullPointerException', 'Derleme hatası'], 'instanceof, sol taraf null olduğunda her zaman false döndürür ve istisna fırlatmaz; bu yüzden ayrı bir null denetimine gerek kalmaz.'),
  ('Java\'da Object sınıfından gelen clone() yöntemi, Cloneable uygulayan bir sınıfta geçersiz kılınmadan kullanılırsa nasıl bir kopya üretir?', 'Alanları birebir kopyalayan sığ bir kopya', ['İç nesneleri de çoğaltan derin bir kopya', 'Yalnız ilkel alanları kopyalayan, başvuruları null bırakan kopya', 'Özgün nesnenin başvurusunu döndüren sahte kopya'], 'Object.clone alanları tek tek kopyalar; başvuru alanları aynı iç nesneleri göstermeye devam eder. Derin kopya gerekiyorsa clone geçersiz kılınıp iç nesneler ayrıca kopyalanmalıdır.'),
  ('Java\'da bir ArrayList for-each döngüsüyle gezilirken döngü içinde liste.remove(oge) çağrılırsa genellikle ne olur?', 'ConcurrentModificationException fırlatılır', ['Öğe sorunsuz silinir ve döngü kalan öğelerle kesintisiz sürer', 'Döngü sessizce baştan başlar', 'Derleme hatası oluşur'], 'Koleksiyonun yineleyicisi \'hızlı başarısız\' (fail-fast) tasarlanmıştır; yineleme sırasında yapısal değişiklik fark edilince istisna fırlatır. Güvenli silme için yineleyicinin remove() yöntemi ya da removeIf kullanılır.'),
  ('Java\'da soyut bir sınıf bir arayüzü implements ile uygulayıp arayüzün yöntemlerinden bazılarını gerçekleştirmezse ne olur?', 'Geçerlidir; eksikleri somut alt sınıflar yazar', ['Derleme hatası; soyut sınıflar arayüz uygulayamaz', 'Eksik yöntemler otomatik olarak boş gövdeyle eklenir', 'Arayüzün eksik yöntemleri çalışma anında silinir'], 'Soyut sınıflar zaten tamamlanmamış olabilir; arayüzden gelen gerçekleştirilmemiş yöntemler soyut kalır ve ilk somut alt sınıf bunları yazmak zorundadır.'),
  ('Java\'da bir sınıfa toString, equals ve hashCode gibi yöntemleri elle yazmak yerine record kullanılması için en uygun durum hangisidir?', 'Değişmez, yalnız veri taşıyan bir sınıf gerektiğinde', ['Durumu sık değişen, karmaşık davranışlı bir sınıf gerektiğinde', 'Başka bir sınıftan kalıtım alması gereken bir sınıfta', 'Alanlarını sonradan setter ile dolduran bir sınıfta'], 'Record\'lar değişmez veri taşıyıcıları için tasarlanmıştır; alanları final\'dır ve başka bir sınıfı genişletemezler. Değişken durumlu ya da kalıtım gerektiren sınıflar için uygun değildirler.'),
  ('Java\'da Hayvan sınıfında protected String ad; alanı var. Başka bir pakette bulunan Kedi extends Hayvan sınıfının yöntemi içinde this.ad okunabilir mi?', 'Evet; alt sınıf kendi nesnesi üzerinden erişebilir', ['Hayır; protected yalnız aynı pakette geçerlidir', 'Hayır; yalnız getter yöntemiyle erişilebilir', 'Evet; ama yalnız Kedi sınıfının static yöntemlerinin içinde'], 'protected üyeler başka paketteki alt sınıflarda da kalıtımla gelen alan olarak, yani alt sınıfın kendi nesneleri üzerinden kullanılabilir.'),
  ('Ruby\'de 5.times { puts "Merhaba" } yazılabilmesi dilin hangi özelliğini yansıtır?', 'Tamsayılar da yöntemleri olan nesnelerdir', ['times bir döngü anahtar sözcüğüdür', '5 değeri önce diziye dönüştürülür', 'puts işlevi kendisine verilen sayıları otomatik olarak tekrarlar'], 'Ruby\'de ilkel tür ayrımı yoktur; 5, Integer sınıfının bir nesnesidir ve times gibi yöntemlere sahiptir.'),
  ('Ruby\'de bir sınıfın içinde attr_accessor :ad yazılması ne sağlar?', 'ad için okuma ve yazma yöntemlerini otomatik üretir', ['ad alanını sınıf değişkeni yapar', 'ad alanını dışarıdan yalnız okunabilir, değiştirilemez yapar', 'ad adlı bir alt sınıf oluşturur'], 'attr_accessor hem ad hem ad= yöntemlerini tanımlar; yalnız okuma için attr_reader, yalnız yazma için attr_writer kullanılır.'),
  ('Python\'da bir nesnenin __del__ yöntemine kaynak kapatma işini bırakmak neden önerilmez?', 'Ne zaman, hatta çağrılıp çağrılmayacağı garanti değildir', ['__del__ yalnız @classmethod süslemeli sınıf yöntemleri olarak tanımlanabilir', '__del__ çağrıldığında nesne iki kez silinir', '__del__ yöntemi Python 3\'te kaldırılmıştır'], '__del__ çağrısı çöp toplamanın zamanlamasına bağlıdır; döngüsel başvurular ya da yorumlayıcının kapanışı gibi durumlarda gecikebilir. Kaynaklar için with ve bağlam yöneticileri kullanılır.'),
  ('Python\'da class Yigin(list): pass tanımlanıp y = Yigin() oluşturulursa y.append(3) ve len(y) çalışır mı?', 'Evet; list\'in bütün yöntemleri devralınır', ['Hayır; yerleşik türlerden türetilemez', 'Yalnız append çalışır, len ise TypeError fırlatır', 'Yalnız len çalışır, append çalışmaz'], 'Python\'da list, dict gibi yerleşik türlerden de türetilebilir; alt sınıf üst türün bütün davranışını devralır. Ancak bu, yığına uygun olmayan insert gibi yöntemleri de açığa çıkarır.'),
  ('Bir fatura programında if tur == "ogrenci" ... elif tur == "emekli" ... gibi uzayan koşullar, her müşteri türü için ayrı alt sınıfın indirim() yöntemini geçersiz kılmasıyla değiştiriliyor. Bu yeniden düzenleme tekniğinin adı nedir?', 'Koşulu çok biçimlilikle değiştirme', ['Yöntemi satır içine alma', 'Sınıfı satır içine alma', 'Değişkenleri anlamlı biçimde yeniden adlandırma'], 'Replace Conditional with Polymorphism tekniğinde tür denetimine dayalı dallar kaldırılır; yeni bir müşteri türü eklemek için var olan koşulları değiştirmek yerine yeni bir alt sınıf yazılır.'),
  ('Çok fazla sorumluluk taşıyan Musteri sınıfındaki adres ile ilgili alan ve yöntemlerin yeni bir Adres sınıfına taşınması hangi yeniden düzenleme tekniğidir?', 'Sınıf çıkarma (extract class)', ['Yöntem çıkarma (extract method)', 'Alt sınıfı aşağı itme (push down)', 'Sınıfı satır içine alma (inline class)'], 'Sınıf çıkarma, bir sınıfın içinde ayrışabilen bir sorumluluk kümesini yeni bir sınıfa taşır ve eski sınıf yeni sınıfı bileşenle kullanır.'),
  ('Muhendis ve Satici alt sınıflarında birebir aynı olan maasHesapla() yönteminin ortak üst sınıf Calisan\'a taşınması hangi yeniden düzenlemedir?', 'Yöntemi yukarı çekme (pull up method)', ['Yöntemi aşağı itme (push down method)', 'Yöntemi taşıma (move method)', 'Yöntemi satır içine alma (inline method)'], 'Pull up method, alt sınıflardaki yinelenen yöntemi üst sınıfa taşıyarak kod tekrarını giderir.'),
  ('Calisan üst sınıfındaki komisyonHesapla() yöntemi yalnız Satici alt sınıfını ilgilendiriyor. Bu yöntemin yalnız Satici\'ya taşınmasına ne ad verilir?', 'Yöntemi aşağı itme (push down method)', ['Yöntemi yukarı çekme (pull up method)', 'Üst sınıf çıkarma (extract superclass)', 'Arayüz çıkarma (extract interface)'], 'Push down method, yalnız bazı alt sınıfları ilgilendiren davranışı üst sınıftan kaldırıp ilgili alt sınıflara taşır; böylece öbür alt sınıflar gereksiz miras taşımaz.'),
  ('rezervasyonYap(String ad, String soyad, String telefon, LocalDate giris, LocalDate cikis, int kisi) gibi uzun parametre listelerinde birlikte gezen değerlerin tek bir nesnede toplanmasına ne ad verilir?', 'Parametre nesnesi oluşturma', ['Yöntemi bölme', 'Parametreyi kaldırma', 'Değişkeni satır içine alma'], 'Birlikte dolaşan değerler (ör. giriş-çıkış tarihi) bir sınıfta toplanınca imza kısalır ve bu değerlere ait doğrulama gibi davranışlar o sınıfa taşınabilir.'),
  ('Muhendis ve Ogretmen sınıflarında ad, soyad, maas alanları ve izinHesapla() yöntemi yineleniyorsa, ortak kısımları yeni bir Calisan sınıfına toplayıp iki sınıfı ondan türetmek hangi tekniktir?', 'Üst sınıf çıkarma (extract superclass)', ['Ortak arayüz çıkarma (extract interface)', 'Alt sınıf çıkarma (extract subclass)', 'Sınıfı satır içine alma (inline class)'], 'Extract superclass, benzer sınıfların ortak alan ve yöntemlerini yeni bir üst sınıfa taşır; böylece tekrar kalkar ve ortak kod bir yerde bakımı yapılır.'),
  ('Kotlin\'de bir alt sınıf, üst sınıfın open fun ciz() yöntemini yeniden tanımlarken hangi anahtar sözcüğü yazmak zorundadır?', 'override', ['virtual', 'new', 'redefine'], 'Kotlin\'de geçersiz kılma açıkça belirtilmelidir; override yazılmazsa aynı imzalı yöntem derleme hatası verir. Böylece yanlışlıkla geçersiz kılma önlenir.'),
  ('Kotlin\'de sınıf gövdesindeki init { require(yas >= 0) } bloğu ne zaman çalışır?', 'Nesne birincil yapıcıyla oluşturulurken', ['Sınıf ilk yüklendiğinde bir kez', 'Nesne çöp toplayıcı tarafından bellekten silinirken', 'Yalnız copy() çağrıldığında'], 'init blokları birincil yapıcının gövdesi gibi davranır; özellik başlatıcılarıyla birlikte yazıldıkları sırada çalışır ve doğrulama için kullanılır.'),
  ('Swift\'te bir sınıf nesnesi bellekten kaldırılmadan hemen önce çalışan, C++\'taki yıkıcının karşılığı olan blok hangisidir?', 'deinit', ['dispose', 'finalize', '~init'], 'Swift\'te deinit, sınıf örneği serbest bırakılırken ARC tarafından otomatik çağrılır; yalnız sınıflarda bulunur, struct\'larda yoktur.'),
  ('C#\'ta static class Matematik olarak bildirilen bir sınıf için hangisi doğrudur?', 'Örneklenemez ve yalnız statik üyeler içerebilir', ['Yalnız bir kez örneklenebilir', 'Yalnız örnek üyeleri içerebilir', 'Başka sınıflar kullanılmadan önce ondan türetilmek zorundadır'], 'C#\'ta statik sınıflar yardımcı yöntemleri toplamak içindir; new ile örneklenemez, kalıtıma kapalıdır ve bütün üyeleri statik olmalıdır.'),
  ('C# 9 ile gelen record Kisi(string Ad, int Yas); türünde iki nesne aynı Ad ve Yas değerlerini taşıyorsa == karşılaştırması ne verir?', 'true; record\'lar değer eşitliği kullanır', ['false; başvurular karşılaştırılır', 'Derleme hatası; record\'lar karşılaştırılamaz', 'Yalnız Ad aynıysa true verir'], 'C# record\'ları için derleyici, bütün özellikleri karşılaştıran eşitlik yöntemleri ve işleçleri üretir; sınıflardaki varsayılan başvuru eşitliğinden farklıdır.'),
  ('C#\'ta using (var dosya = new StreamReader("a.txt")) { ... } bloğunun çalışabilmesi için StreamReader hangi arayüzü uygulamalıdır?', 'IDisposable', ['IComparable', 'IEnumerable', 'ICloneable'], 'using bloğu sonunda nesnenin Dispose() yöntemi çağrılır; bu yüzden nesne IDisposable arayüzünü uygulamalıdır. Java\'daki AutoCloseable\'ın karşılığıdır.'),
  ('Go\'da func (d Daire) Alan() float64 { ... } bildirimindeki (d Daire) kısmına ne ad verilir?', 'Alıcı (receiver)', ['Yapıcı (constructor)', 'Arayüz (interface)', 'Gömülü alan (embedded field)'], 'Go\'da yöntemler türün içine değil dışına yazılır; func ile ad arasındaki alıcı parametresi yöntemin hangi türe ait olduğunu belirtir.'),
  ('PHP\'de bir sınıfın yapıcı yöntemi hangi adla tanımlanır?', '__construct', ['__init__', 'constructor', '__new__'], 'PHP 5\'ten beri yapıcılar function __construct() ile tanımlanır; nesne içinden alanlara \$this->alan biçiminde erişilir.'),
  ('Dörtlü Çete\'nin tasarım kalıplarının çoğunun altında yatan \'değişeni kapsülle\' (encapsulate what varies) ilkesi neyi önerir?', 'Sık değişecek kısmı ayırıp kararlı kodun arkasına saklamayı', ['Değişebilecek bütün alanları herkese açık (public) yapmayı', 'Değişebilecek kodu her sınıfa kopyalamayı', 'Değişen kısımlar için yalnız static yöntemler yazmayı'], 'Değişen davranış (ör. indirim hesabı) ayrı bir sınıfa ya da arayüze taşınınca değişiklikler yalnız orada yapılır, sistemin geri kalanı etkilenmez. Strategy ve State bu ilkenin örnekleridir.'),
  ('Alan nesnelerine sanki bellekte bir koleksiyondaymış gibi ekle, bul, sil yöntemleriyle erişilmesini sağlayıp veritabanı ayrıntılarını gizleyen kalıp hangisidir?', 'Repository (depo)', ['Singleton (tekil)', 'Flyweight (sinek siklet)', 'Memento (hatıra)'], 'Depo kalıbı, kalıcılık mantığını alan modelinden ayırır; iş kodu yalnız OgrenciDeposu gibi bir arayüzle konuşur ve veri kaynağı değişse bile etkilenmez.'),
  ('Katmanlar ya da ağ üzerindeki sistemler arasında yalnız veri taşımak için kullanılan, davranış içermeyen basit nesnelere ne ad verilir?', 'Veri aktarım nesnesi (DTO)', ['Değer nesnesi (value object)', 'Tanrı nesnesi (God object)', 'Vekil nesne (proxy)'], 'DTO\'lar çok sayıda alanı tek seferde taşıyarak uzak çağrı sayısını azaltır; iş kuralı içermezler ve çoğu zaman yalnız alan ve erişimcilerden oluşurlar.'),
  ('Bir kahve sınıfının sütlü, şekerli, kremalı her bileşimi için ayrı alt sınıf yazmak yerine Decorator kullanmanın sağladığı başlıca kazanç nedir?', 'Bileşim sayısı kadar sınıf yazmaktan kurtarır', ['Nesnelerin bellekte daha az yer kaplamasını sağlar', 'Kalıtımı tamamen yasaklar', 'Bütün eklentileri tek bir yönteme sığdırır'], 'Üç eklentinin bütün bileşimleri için kalıtımla yedi ayrı alt sınıf gerekirdi; süsleyicilerle üç sınıf yazılıp çalışma anında istenildiği gibi üst üste giydirilir.'),
  ('Java\'da Runtime.getRuntime() çağrısının her seferinde uygulamanın çalışma ortamını temsil eden aynı nesneyi döndürmesi hangi kalıbın örneğidir?', 'Singleton', ['Prototype', 'Decorator', 'Command'], 'Runtime sınıfının yapıcısı özeldir ve her Java uygulamasında tek bir Runtime örneği bulunur; erişim statik getRuntime() yöntemiyle sağlanır.'),
  ('Python\'da A\'nın __init__\'i self.x = 1, B(A)\'nın __init__\'i önce self.y = 2 sonra super().__init__() çalıştırıyor. b = B() sonrasında b.x + b.y kaçtır?', '3', ['2', '1', 'AttributeError'], 'super().__init__() B\'nin __init__\'i içinde, y atandıktan sonra çağrılsa da A\'nın __init__\'ini çalıştırır ve x\'i oluşturur; Python\'da üst başlatıcının ilk satırda çağrılması zorunlu değildir.'),
  ('C++\'ta Nokta dizi[3]; satırı çalıştığında Nokta sınıfının varsayılan yapıcısı kaç kez çağrılır?', '3', ['1', '0', '4'], 'Nesne dizisinin her öğesi ayrı bir nesnedir ve her biri varsayılan yapıcıyla oluşturulur; Nokta\'nın varsayılan yapıcısı yoksa bu satır derlenmez.'),
  ('C++\'ta büyük bir Resim nesnesini alan işlevin void isle(Resim r) yerine void isle(const Resim& r) biçiminde yazılması neden tercih edilir?', 'Nesne kopyalanmaz ve işlev onu değiştiremez', ['Nesne işlev içinde otomatik olarak silinir', 'İşlev daha fazla parametre alabilir', 'Nesne her çağrıda derin kopyalanır'], 'Değerle aktarımda her çağrıda kopya yapıcı çalışır; sabit başvuru kopyalama maliyetini ortadan kaldırırken const sayesinde çağıranın nesnesinin değişmeyeceğini de garanti eder.'),
  ('JavaScript\'te s.artir yöntemi bir değişkene atanıp tek başına çağrılınca this kaybolur. const f = s.artir.bind(s); satırı bu sorunu nasıl çözer?', 'this\'i kalıcı olarak s\'ye bağlı yeni bir işlev döndürür', ['s.artir yöntemini s\'den kalıcı olarak siler', 'f işlevini new ile çağrılabilen bağımsız bir sınıfa dönüştürür', 's nesnesinin derin kopyasını oluşturur'], 'bind, verilen nesneyi this olarak sabitleyen yeni bir işlev üretir; f nasıl çağrılırsa çağrılsın içindeki this s olur.'),
  ('Java\'da A sınıfının yalnız A(int x) yapıcısı var. B extends A sınıfında B(int x) { super(x); } yerine yalnız B() { super(0); } yazılmışsa new B(5) çağrısı için ne söylenebilir?', 'Derleme hatası; Java\'da yapıcılar kalıtılmaz', ['A(int) yapıcısı devralındığı için çalışır', 'B() yapıcısı çağrılır ve verilen 5 argümanı sessizce yok sayılır', 'Çalışma anında istisna fırlatılır'], 'Java\'da yapıcılar alt sınıfa geçmez; B\'de int alan bir yapıcı tanımlanmadıkça new B(5) derlenmez.'),
  ('Python\'da bir sınıfta @property ile tanımlanan sayac özelliğinin okuma yöntemi her çağrıldığında içte bir değeri 1 artırıp döndürüyor ve ilk değer 0. print(n.sayac, n.sayac, n.sayac) ne yazdırır?', '1 2 3', ['1 1 1', '0 0 0', '3 3 3'], 'Özellik okumak her seferinde bir yöntem çağrısıdır; bu yüzden yan etkili bir okuma yöntemi her erişimde farklı sonuç verir. Bu tür yan etkiler genellikle önerilmez.'),
  ('Java\'da Sekil[] s = new Sekil[5]; satırı çalıştığında kaç Sekil nesnesi oluşturulur?', 'Hiç; yalnız null tutan 5 başvuruluk dizi oluşur', ['5 nesne, her biri Sekil sınıfının varsayılan yapıcısıyla', '1 nesne, dizinin ilk öğesi için', 'Sekil soyut değilse 5, soyutsa 0'], 'Java\'da nesne dizisi oluşturmak yalnız başvuru yuvaları ayırır; her öğe null\'dur ve nesneler ayrıca new ile oluşturulmalıdır. C++\'taki nesne dizilerinden farklıdır.'),
  ('Python\'da Kisi nesneleri için __lt__ yaşa göre tanımlı. kisiler listesinin max(kisiler) çağrısı neyi döndürür?', 'En yaşlı kişiyi', ['En genç kişiyi', 'Listedeki son kişiyi', 'TypeError'], 'max ve min öğeleri < işleciyle karşılaştırır; __lt__ yaşa göre tanımlı olduğundan en büyük yaşlı nesne döner.'),
  ('Nesnelerin kalıtım, başvuru ve koleksiyonlarla kurduğu yapı ile ilişkisel veritabanlarının tablo ve yabancı anahtarlı yapısı arasındaki uyumsuzluğa ne ad verilir?', 'Nesne-ilişkisel empedans uyumsuzluğu', ['Çok biçimlilik çakışması', 'Elmas problemi', 'Kırılgan taban sınıf (fragile base class) problemi'], 'Kalıtım, nesne kimliği ve gezinilebilir başvurular tablolara doğrudan karşılık gelmez; ORM araçları bu uyumsuzluğu azaltmak için geliştirilmiştir.'),
  ('Bir okul sisteminde bir öğrenci birçok derse kayıt olabiliyor, bir derste de birçok öğrenci bulunuyor; ikisi de birbirinden bağımsız var olabiliyor. Bu iki sınıf arasındaki ilişki en iyi nasıl tanımlanır?', 'Çoka çok ilişkilendirme (association)', ['Bileşim (composition) ilişkisi, ders öğrencinin parçası', 'Kalıtım (inheritance)', 'Bire bir bileşim'], 'Ne öğrenci dersin parçası ne de ders öğrencinin parçasıdır; yaşam döngüleri bağımsızdır. Bu yüzden iki yönde de çokluk taşıyan bir ilişkilendirme uygundur.'),
  ('Java\'da ilkel türler nesne değildir. Smalltalk ve Ruby gibi dillerle karşılaştırıldığında bunun bir sonucu hangisidir?', '5 gibi bir değer üzerinde doğrudan yöntem çağrılamaz', ['Java\'da sayılarla aritmetik işlem yapılamaz', 'Java\'da sayılar diziye konamaz', 'Java\'da sayılar yöntemlere parametre olarak verilemez'], 'Java\'da 5.toString() yazılamaz; ilkel değerin bir sarmalayıcı nesneye dönüştürülmesi gerekir. Her şeyin nesne olduğu dillerde ise sayılar doğrudan mesaj alabilir.'),
  ('Bir arayüzü değiştirmeden yalnız arkasındaki sınıfın değiştirilmesi, sistemin geri kalanını etkilemez. Bu durum en çok hangi kavramın yararını gösterir?', 'Arayüzün gerçekleştirimden ayrılması', ['Çoklu kalıtımın bütün sınıflarda kullanılması', 'İşleç aşırı yüklemesi', 'Statik bağlama'], 'İstemciler yalnız arayüze bağımlı olduğunda gerçekleştirim serbestçe değiştirilebilir; bu, modüler ve bakımı kolay sistemlerin temelidir.'),
  ('C#\'ta Kopek k = hayvan as Kopek; ifadesinde hayvan nesnesi aslında bir Kedi ise ne olur?', 'k değişkeni null olur', ['InvalidCastException fırlatılır', 'Derleme hatası oluşur', 'Kedi nesnesi Kopek\'e dönüştürülür'], 'as işleci dönüşüm başarısızsa istisna fırlatmak yerine null döndürür; (Kopek)hayvan biçimindeki açık dönüşüm ise InvalidCastException fırlatır.'),
  ('Java\'da int[] a = {1, 2}; int[] b = {1, 2}; için a.equals(b) ifadesi neden false verir?', 'Diziler equals\'ı geçersiz kılmaz; kimlik karşılaştırılır', ['Diziler farklı uzunlukta sayılır', 'int dizileri hiçbir zaman eşit olamaz', 'equals yöntemi yalnız String ve sarmalayıcı sınıflarda çalışır'], 'Diziler Object\'in equals yöntemini olduğu gibi devralır ve yalnız aynı dizi nesnesi için true verir. İçerik karşılaştırmak için Arrays.equals(a, b) kullanılır.'),
  ('Java\'da List<Integer> liste = List.of(1, 2); liste.add(3); satırları çalışınca ne olur?', 'UnsupportedOperationException fırlatılır', ['Liste [1, 2, 3] olur', 'Derleme hatası oluşur', '3 yok sayılır, liste değişmez'], 'List.of değiştirilemez bir liste döndürür; ekleme ve silme yöntemleri bu nesnede desteklenmez ve çalışma anında istisna fırlatır.'),
  ('Java\'da Kisi sınıfı Comparable<Kisi> uygulayıp compareTo\'da yaşları karşılaştırıyor; Collections.sort(liste) çağrılıyor. Aynı listeyi bu kez ada göre sıralamak için sınıfı değiştirmeden ne yapılır?', 'Ada göre karşılaştıran bir Comparator verilir', ['compareTo yöntemi ikinci kez tanımlanır', 'Kisi sınıfından compareTo\'yu geçersiz kılan AdaGoreKisi türetilir', 'Liste önce ters çevrilip yeniden sıralanır'], 'Collections.sort(liste, Comparator.comparing(Kisi::getAd)) gibi bir çağrı, doğal sıralamaya dokunmadan başka bir ölçüt uygular.'),
  ('Bir sınıfın her public yönteminin çağrılmasından önce ve sonra her zaman doğru kalması gereken koşula (ör. \'bakiye hiçbir zaman negatif olamaz\') ne ad verilir?', 'Sınıf değişmezi (class invariant)', ['Döngü değişmezi (loop invariant)', 'Ön koşul (precondition) bildirimi', 'Tür parametresi (type parameter)'], 'Sınıf değişmezi nesnenin tutarlı durumunu tanımlar; yapıcı bu koşulu kurmalı, her public yöntem de onu bozmadan bırakmalıdır.'),
  ('Geçersiz durumdaki nesnelerin hiç oluşmaması için girdi denetimi en başta nerede yapılmalıdır?', 'Yapıcıda; geçersiz girdide istisna fırlatılarak', ['Her getter yönteminin içinde, değer okunurken', 'Nesne ilk kez yazdırılırken', 'Program kapanırken çalışan kodda'], 'Yapıcıda doğrulama yapan ve geçersiz girdide hemen istisna fırlatan nesneler, oluşturuldukları andan itibaren sınıf değişmezini sağlar; hatalar da kaynağına yakın yerde yakalanır.'),
  ('Değişmez gibi davranan bir nesnenin, birden çok kullanıcı tarafından paylaşılıp yalnız biri değişiklik yapmak istediğinde kopyalanmasına dayanan tekniğe ne ad verilir?', 'Yazınca kopyala (copy-on-write)', ['Okuyunca sil (delete-on-read)', 'Tembel silme (lazy deletion) yöntemi', 'Derin bağlama (deep binding)'], 'Copy-on-write, gereksiz kopyalamayı değişiklik anına kadar erteler; Java\'daki CopyOnWriteArrayList ve birçok işletim sistemi bu fikri kullanır.'),
  ('Java\'da Math ve Collections gibi yalnız statik yöntemlerden oluşan yardımcı sınıfların yapıcısının genellikle private yapılmasının nedeni nedir?', 'Anlamsız biçimde örneklenmelerini engellemek', ['Statik yöntemlerin çalışabilmesi için zorunlu olması', 'Sınıfın alt sınıflarda genişletilmesini kolaylaştırmak', 'Yöntemlerin daha hızlı çalışmasını sağlamak'], 'Durum taşımayan yardımcı sınıfın nesnesi bir işe yaramaz; özel yapıcı hem new ile örneklemeyi hem de kalıtımı engeller.'),
  ('JavaBean olarak adlandırılan sınıflardan geleneksel olarak beklenen özellik hangisidir?', 'Parametresiz bir public yapıcıya sahip olmaları', ['Hiç alan içermemeleri', 'Yalnız statik yöntemler içermeleri', 'Bir çatıya özgü soyut arayüzden türetilmiş olmaları'], 'JavaBean geleneğinde sınıfın parametresiz public yapıcısı, get/set yöntemleriyle erişilen özel alanları vardır ve genellikle Serializable\'dır; araçlar bu nesneleri yansımayla kurabilir.'),
  ('Herhangi bir çatıya özgü sınıftan türemeyen, özel arayüz uygulamayan sade Java nesnelerini anlatmak için kullanılan kısaltma hangisidir?', 'POJO', ['JVM', 'DTO', 'API'], 'Plain Old Java Object, sınıfın belirli bir çatıya bağımlı olmadığını vurgular; Martin Fowler ve arkadaşlarının 2000\'de yaygınlaştırdığı bir terimdir.'),
  ('Nesne yönelimli terminolojide bir yöntemin \'imzası\', aşırı yükleme açısından genellikle hangi öğelerden oluşur?', 'Yöntemin adı ve parametre türlerinin sırası', ['Yöntemin adı ile dönüş türü ve fırlattığı istisnalar', 'Yöntemin gövdesindeki satır sayısı', 'Yöntemin erişim belirleyicisi ve adı'], 'Java ve C# gibi dillerde aşırı yüklenmiş yöntemler ad ile parametre türlerinden oluşan imzalarına göre ayırt edilir; dönüş türü ve erişim düzeyi imzaya dahil değildir.'),
  ('Python\'da kendi Sozluk benzeri sınıfında d["anahtar"] = 5 ataması yapılabilmesi için hangi yöntem tanımlanmalıdır?', '__setitem__', ['__getitem__', '__assign__', '__setattr__'], 'Köşeli parantezle atama __setitem__(self, anahtar, deger) çağrısına dönüşür; okuma __getitem__, silme __delitem__ ile yapılır. __setattr__ ise nokta ile yapılan nitelik atamasıdır.'),
  ('Python\'da Vektor sınıfının nesneleri için -v ifadesinin her bileşeni ters işaretli yeni bir vektör vermesi isteniyor. Hangi yöntem tanımlanmalıdır?', '__neg__', ['__sub__', '__inv__', '__minus__'], 'Tekli eksi işleci __neg__ yöntemine karşılık gelir; ikili çıkarma ise __sub__ ile tanımlanır.'),
  ('C#\'ta delegate anahtar sözcüğüyle tanımlanan türler neyi temsil eder?', 'Belirli bir imzaya uyan yöntemlere tür güvenli başvuruları', ['Başka bir sınıfa özel üyelere erişim yetkisi veren erişim belirleyicilerini', 'Yalnız arayüzlerde kullanılabilen soyut sınıfları', 'Çalışma anında oluşturulan yeni iş parçacıklarını'], 'Temsilciler (delegate) yöntemleri değişken gibi saklamayı ve geçirmeyi sağlar; olay sistemi ve lambda ifadeleri bunların üzerine kuruludur.'),
  ('Java Swing\'de bir düğmeye tıklandığında çalışacak kod, ActionListener arayüzünü uygulayan bir nesnenin hangi yöntemine yazılır?', 'actionPerformed', ['onClick', 'handleEvent', 'runListener'], 'ActionListener\'ın tek soyut yöntemi actionPerformed(ActionEvent e)\'dir; düğme, kayıtlı dinleyicilerin bu yöntemini çağırır. Bu, Observer kalıbının bir uygulamasıdır.'),
  ('Kotlin\'de val ayar: Ayar by lazy { yukle() } bildirimi ne sağlar?', 'yukle() ilk erişimde bir kez çalışır, sonuç saklanır', ['yukle() her erişimde yeniden çalışır', 'yukle() nesne oluşturulurken, yapıcı bitmeden hemen çalışır', 'ayar değeri hiçbir zaman başlatılmaz'], 'by lazy bir özellik yetkilendirmesidir; değer ilk okumada hesaplanır ve sonraki okumalarda aynı değer döner. Varsayılan olarak iş parçacığı açısından güvenlidir.'),
  ('Spring gibi çatıların çekirdeğinde bulunan ve nesneleri oluşturup bağımlılıklarını birbirine bağlayan bileşene genel olarak ne ad verilir?', 'IoC (bağımlılık enjeksiyonu) kabı', ['Çöp toplayıcı', 'Sınıf yükleyici', 'Derleyicinin makro ön işlemcisi'], 'IoC kabı yapılandırmaya ya da ek açıklamalara bakarak hangi nesnenin hangi bağımlılıkla oluşturulacağına karar verir ve nesnelerin yaşam döngüsünü yönetir.'),
  ('JavaScript\'te class Kedi { static olustur() { return new Kedi(); } } tanımlı. const k = new Kedi(); k.olustur(); çağrısı ne yapar?', 'TypeError; olustur nesnede değil sınıfta tanımlıdır', ['Yeni bir Kedi nesnesi döndürür', 'undefined döndürür ve herhangi bir hata vermeden devam eder', 'k nesnesinin kendisini döndürür'], 'Statik yöntemler sınıf işlevinin kendisine eklenir, prototipe eklenmez; bu yüzden yalnız Kedi.olustur() biçiminde çağrılabilir.'),
  ('Bir nesnenin alanları aracılığıyla eriştiği bütün nesnelerin, onların da eriştiği nesnelerle birlikte oluşturduğu ağ yapısına ne ad verilir?', 'Nesne grafiği (object graph)', ['Sınıf hiyerarşisi (class hierarchy)', 'Çağrı yığını', 'Kalıtım ağacı'], 'Nesne grafiği çalışma anındaki başvuru ilişkilerini gösterir; serileştirme, derin kopyalama ve çöp toplama bu grafiği dolaşarak çalışır.'),
  ('Java\'da class A { int x = 5; A() { x = x * 2; } } tanımlı. new A().x kaçtır?', '10', ['5', '0', 'Derleme hatası'], 'Alan başlatıcıları, üst sınıf yapıcısından sonra ve yapıcı gövdesinden önce çalışır; x önce 5 olur, ardından gövdede iki katına çıkar.'),
  ('C++\'ta static üye işlevlerle ilgili hangisi doğrudur?', 'this işaretçileri yoktur, örnek üyelerine doğrudan erişemezler', ['Yalnız sanal (virtual) olarak bildirilebilir ve alt sınıflarda geçersiz kılınabilirler', 'Her nesne için ayrı bir kopyaları bulunur', 'Yalnız const nesneler üzerinden çağrılabilirler'], 'Statik üye işlevler belirli bir nesneye bağlı değildir; bu yüzden this kullanamaz ve sanal olamazlar. Sinif::islev() biçiminde çağrılırlar.'),
  ('Java\'da soyut bir sınıf final yöntemler içerebilir mi?', 'Evet; bu yöntemler alt sınıflarda değiştirilemez', ['Hayır; soyut sınıfta final kullanılamaz', 'Evet; ama alt sınıflar onları geçersiz kılmak zorundadır', 'Hayır; final yöntemler yalnız arayüzlerde olur'], 'Soyut sınıf bazı yöntemleri soyut bırakırken, değişmemesi gereken iskelet yöntemleri final yapabilir; şablon yöntem kalıbında bu sık görülür.'),
  ('UML sınıf diyagramında bir kutunun ad bölümünde «interface» yazılması neyi gösterir ve bu gösterime ne ad verilir?', 'Kutunun bir arayüz olduğunu; klişe (stereotype) gösterimi', ['Kutunun bir paket olduğunu; çokluk gösterimi', 'Kutunun soyut bir sınıf olduğunu; kısıt (constraint) gösterimi', 'Kutunun bir nesne olduğunu; etiket gösterimi'], 'Açılı tırnaklar içindeki klişeler bir UML öğesinin türünü ya da rolünü belirtir; «interface», «enumeration» gibi.'),
  ('Python\'da Kisi sınıfında tanımlı selam yöntemi için Kisi.selam(k) ve k.selam() çağrıları arasındaki ilişki nedir?', 'İkisi eşdeğerdir; ilkinde nesne açıkça verilir', ['İlki her zaman TypeError verir', 'İkincisi sınıf yöntemini, ilki örnek yöntemini çağırır', 'İlki yeni bir Kisi nesnesi oluşturur'], 'Sınıf üzerinden erişilen yöntem sıradan bir işlevdir ve self\'i açıkça bekler; nesne üzerinden erişildiğinde ise nesne self\'e otomatik bağlanır.'),
  ('Java\'da class A { A() { this(5); yaz("1"); } A(int x) { yaz("2"); } } tanımlı. new A() çıktısı nedir?', '21', ['12', '1', '2'], 'Parametresiz yapıcı önce this(5) ile öbür yapıcıyı çağırır ve o 2 yazdırır; denetim geri dönünce kalan satır 1 yazdırır.'),
  ('JavaScript\'te Object.assign(Kedi.prototype, yuzebilirMixin) satırı ne yapar?', 'Mixin nesnesinin yöntemlerini Kedi\'nin prototipine kopyalar', ['Kedi\'yi yuzebilirMixin\'den türetilmiş bir sınıf yapar', 'yuzebilirMixin nesnesini Kedi sınıfının yeni bir örneğine dönüştürüp prototipe bağlar', 'Kedi prototipini dondurup değiştirilemez yapar'], 'JavaScript\'te mixin\'ler genellikle bir nesnedeki yöntemlerin başka bir sınıfın prototipine kopyalanmasıyla uygulanır; böylece Kedi nesneleri bu yöntemleri prototip zincirinden kullanır.'),
  ('C++11\'de bir sanal üye işlevin sonuna final yazılması (void ciz() final;) neyi sağlar?', 'İşlevin alt sınıflarda yeniden geçersiz kılınmasını engeller', ['İşlevi saf sanal hale getirir', 'İşlevin program boyunca yalnız bir kez çağrılmasına izin verir, sonra siler', 'İşlevi statik bağlamaya zorlar ve sanallığı kaldırır'], 'final belirleyicisi, geçersiz kılma zincirini o sınıfta sonlandırır; sınıf adının ardından yazıldığında ise sınıftan türetmeyi engeller.'),
  ('C++\'ta Java\'daki arayüzlerin karşılığı olarak genellikle hangi yapı kullanılır?', 'Saf sanal işlevlerden ve sanal yıkıcıdan oluşan soyut sınıf', ['Yalnız statik üye işlevlerden ve sabitlerden oluşan bir struct tanımı', 'friend işlevlerle dolu bir ad alanı', 'Bütün üyeleri private olan bir şablon sınıf'], 'C++\'ta ayrı bir interface anahtar sözcüğü yoktur; durum taşımayan, bütün işlevleri = 0 olan bir soyut sınıf arayüz görevini görür ve çoklu kalıtımla uygulanabilir.'),
  ('Java\'da Sekil soyut bir sınıfken Sekil s = new Sekil() { double alan() { return 4; } }; satırı için hangisi doğrudur?', 'Geçerlidir; Sekil\'in adsız bir alt sınıfı oluşturulur', ['Derleme hatası; soyut sınıf örneklenemez', 'Geçerlidir; Sekil sınıfının kendisinden nesne oluşur', 'Derlenir ama çalışma anında InstantiationException istisnası fırlatılır'], 'Süslü parantezli bu yazım anonim bir alt sınıf tanımlar ve eksik soyut yöntemleri tamamlar; oluşturulan nesne Sekil değil, onun adsız alt sınıfının örneğidir.'),
  ('Python\'da __call__ yöntemi tanımlanmış bir sınıfın nesnesi n için callable(n) ne döndürür?', 'True', ['False', 'None', 'TypeError'], 'callable, nesnenin işlev gibi çağrılıp çağrılamayacağını sınar; __call__ tanımlı sınıfların nesneleri, işlevler ve sınıfların kendileri çağrılabilir sayılır.'),
  ('C++\'ta nesne oluştururken malloc yerine new kullanılmasının nesne yönelimli açıdan temel nedeni nedir?', 'new belleği ayırmakla kalmaz, yapıcıyı da çağırır', ['malloc öbek yerine yığından bellek ayırır', 'new her zaman daha az bellek kullanır', 'malloc yalnız int ve double gibi ilkel türler için derlenebilir'], 'malloc yalnız ham bellek döndürür ve nesneyi başlatmaz. new hem bellek ayırır hem yapıcıyı çalıştırır; delete de yıkıcıyı çağırdıktan sonra belleği bırakır.'),
  ('Python\'da bir üst sınıf yönteminin alt sınıflarca mutlaka yazılması gerektiğini, abc modülü kullanmadan belirtmenin yaygın yolu hangisidir?', 'Yöntem gövdesinde raise NotImplementedError yazmak', ['Yöntemi boş bırakıp pass yazmak', 'Yöntemin adını büyük harfle yazıp başına alt çizgi koymak', 'Yöntemi @staticmethod ile süslemek'], 'NotImplementedError, yöntem alt sınıfta yazılmadan çağrılırsa açık bir hata verir. abc\'den farklı olarak nesne oluşturmayı engellemez; hata yalnız çağrı anında ortaya çıkar.'),
];
